function stageStatus(stage) {
  return stage?.webgpuStatus?.status || stage?.status || 'missing';
}

function executionBackend(stages) {
  const backends = stages.map((stage) => stage?.backend || 'missing');
  if (backends.every((backend) => backend === 'webgpu')) return 'webgpu';
  if (backends.every((backend) => backend === 'cpu-reference')) return 'cpu-reference';
  return 'mixed-fallback';
}

function hasRetainedStageBuffers({ p2gGridProjection, gridUpdate }) {
  const retainedDenseGrid = Boolean(
    (p2gGridProjection?.gpuResult?.gridBuffer || p2gGridProjection?.gridBuffer)
    && (gridUpdate?.gpuResult?.updatedGridBuffer || gridUpdate?.updatedGridBuffer)
  );
  if (retainedDenseGrid) return true;
  const fieldExecution = p2gGridProjection?.mechanicsFieldViewExecution ?? null;
  const fieldBuffer = p2gGridProjection?.mechanicsFieldViewBuffer ?? null;
  if (!fieldExecution || !fieldBuffer) return false;
  const sourceProjection = gridUpdate?.sourceProjection ?? null;
  const sourceProjectionMatches = sourceProjection === p2gGridProjection
    || Boolean(
      sourceProjection?.backend === 'webgpu'
      && sourceProjection.mechanicsFieldViewEnabled === true
      && sourceProjection.mechanicsFieldViewExecution === fieldExecution
      && sourceProjection.mechanicsFieldViewBuffer === fieldBuffer
      && sourceProjection.mechanicsFieldMutationOutputOrdinal
        === p2gGridProjection.mechanicsFieldMutationOutputOrdinal
      && sourceProjection.mechanicsFieldMutationOutputStateEncoding
        === p2gGridProjection.mechanicsFieldMutationOutputStateEncoding
    );
  try {
    return Boolean(
      p2gGridProjection?.backend === 'webgpu'
      && gridUpdate?.backend === 'webgpu'
      && p2gGridProjection?.mechanicsFieldViewEnabled === true
      && gridUpdate?.mechanicsFieldViewEnabled === true
      && gridUpdate.mechanicsFieldViewExecution === fieldExecution
      && gridUpdate.mechanicsFieldViewBuffer === fieldBuffer
      && sourceProjectionMatches
      && p2gGridProjection.gridBuffer == null
      && gridUpdate.updatedGridBuffer == null
      && p2gGridProjection.denseGridAuthoritative === false
      && gridUpdate.denseGridAuthoritative === false
      && p2gGridProjection.gridStateAuthority
        === 'schroeder-spatial-mechanics-field-view-v1'
      && gridUpdate.gridStateAuthority
        === 'schroeder-spatial-mechanics-field-view-v1'
      && Number(p2gGridProjection.mechanicsFieldViewByteLength) > 0
      && p2gGridProjection.mechanicsFieldViewByteLength
        === gridUpdate.mechanicsFieldViewByteLength
      && gridUpdate.mechanicsFieldMutationInputOrdinal
        === p2gGridProjection.mechanicsFieldMutationOutputOrdinal
      && gridUpdate.mechanicsFieldMutationOutputOrdinal
        === gridUpdate.mechanicsFieldMutationInputOrdinal + 1
      && p2gGridProjection.mechanicsFieldMutationOutputStateEncoding
        === SCHROEDER_SPATIAL_MECHANICS_FIELD_STATE_ENCODING_MASS_MOMENTUM_GRADIENT
      && gridUpdate.mechanicsFieldMutationOutputStateEncoding
        === SCHROEDER_SPATIAL_MECHANICS_FIELD_STATE_ENCODING_MASS_VELOCITY_GRADIENT
      && fieldExecution.ownerRuntime?.ownsExecution?.(fieldExecution) === true
      && fieldExecution.ownerRuntime?.isExecutionSubmitted?.(fieldExecution) === true
    );
  } catch {
    return false;
  }
}

function retainedSchroederParticleStorageMaterializationBuffers(schroederParticleStorageMaterialization) {
  const source = schroederParticleStorageMaterialization?.result || schroederParticleStorageMaterialization;
  return {
    source,
    stateBuffer: source?.particleStateBuffer || source?.stateBuffer || source?.outputStateBuffer || null,
    thermoBuffer: source?.particleThermoBuffer || source?.thermoBuffer || source?.outputThermoBuffer || null,
    mechanicsBuffer: source?.particleMechanicsBuffer || source?.mechanicsBuffer || source?.outputMechanicsBuffer || null,
    identityBuffer: source?.particleIdentityBuffer || source?.identityBuffer || source?.outputIdentityBuffer || null,
    materializationBuffer: source?.materializationBuffer || null,
    stateBufferByteLength: source?.stateBufferByteLength ?? source?.stateByteLength ?? 0,
    thermoBufferByteLength: source?.thermoBufferByteLength ?? source?.thermoByteLength ?? 0,
    mechanicsBufferByteLength: source?.mechanicsBufferByteLength ?? source?.mechanicsByteLength ?? 0,
    identityBufferByteLength: source?.identityBufferByteLength ?? source?.identityByteLength ?? 0,
    identityStrideBytes: source?.identityStrideBytes ?? 0,
    identitySchema: source?.identitySchema ?? null,
    identityRequired: source?.identityRequired === true,
    particleIdentityMutationApproved: source?.particleIdentityMutationApproved === true,
    identityRevision: source?.identityRevision ?? null,
    renderDomainKeys: { ...(source?.renderDomainKeys || {}) },
    materializationBufferByteLength: source?.materializationBufferByteLength ?? source?.materializationByteLength ?? 0,
    destroyParticleBuffers: source?.destroyParticleBuffers || null,
    destroyMaterializationBuffer: source?.destroyMaterializationBuffer || null
  };
}

export function createSchroederParticleStorageAdoption({
  schroederParticleStorageMaterialization = null,
  sphParticleState = null,
  mlsMpmParticleState = null
} = {}) {
  const retained = retainedSchroederParticleStorageMaterializationBuffers(
    schroederParticleStorageMaterialization
  );
  const source = retained.source;
  if (!source) return null;
  const warnings = [];
  const blockers = [];
  const identityRequired = retained.identityRequired
    || sphParticleStateRequiresExplicitIdentity(sphParticleState);
  const particleIdentityMutationApproved = retained.particleIdentityMutationApproved === true;
  const targetStateFamilies = Array.isArray(source.targetStateFamilies)
    ? [...source.targetStateFamilies]
    : [];
  const requiredTargetStateFamilies = identityRequired
    ? SCHROEDER_PARTICLE_STORAGE_TARGET_FAMILY_NAMES
    : SCHROEDER_PARTICLE_STORAGE_TARGET_FAMILY_NAMES.filter((family) => (
      family !== 'sph-particle-identity'
    ));
  const targetStateFamiliesAccepted = targetStateFamilies.length === 0
    ? !identityRequired
    : requiredTargetStateFamilies.every((family) => targetStateFamilies.includes(family));
  const admitted = source.particleStorageMaterializationAdmissionApproved === true
    || source.stateAuthorityStatus === 'state-manager-admitted-particle-storage-materialization-materialized';
  const submitted = source.status === 'schroeder-particle-storage-materialization-submitted'
    || source.schema === ULG_SCHROEDER_PARTICLE_STORAGE_MATERIALIZATION_EXECUTION_SCHEMA
    // Compacted storage presents the same retained-buffer interface with an
    // explicit (possibly negative) admitted count delta.
    || source.status === 'schroeder-particle-storage-compaction-submitted'
    || source.schema === ULG_SCHROEDER_PARTICLE_STORAGE_COMPACTION_EXECUTION_SCHEMA;
  const retainedParticleBuffers = source.retainedParticleBuffers !== false
    && Boolean(retained.stateBuffer && retained.thermoBuffer && retained.mechanicsBuffer);
  const stablePhaseCarrierPairsRequired = Boolean(
    phaseCarrierPlanReady(sphParticleState?.phaseCarrierPlan)
  );
  if (!admitted) blockers.push('schroeder-particle-storage-materialization-not-admitted');
  if (!submitted) blockers.push('schroeder-particle-storage-materialization-not-submitted');
  if (!targetStateFamiliesAccepted) blockers.push('schroeder-particle-storage-target-families-incomplete');
  if (!retainedParticleBuffers) blockers.push('schroeder-particle-storage-materialization-buffers-missing');
  if (stablePhaseCarrierPairsRequired) {
    blockers.push('schroeder-particle-storage-materialization-not-phase-pair-aware');
  }
  if (targetStateFamilies.length === 0) warnings.push('schroeder-particle-storage-target-families-implicit');
  const sourceParticleCount = Math.max(0, Math.round(finiteNumber(
    source.sourceParticleCount ?? sphParticleState?.particleCount,
    sphParticleState?.particleCount ?? 0
  )));
  const outputParticleCapacity = Math.max(sourceParticleCount, Math.round(finiteNumber(
    source.outputParticleCapacity ?? source.particleCapacity ?? sourceParticleCount,
    sourceParticleCount
  )));
  const identityStrideBytes = Math.max(0, Math.round(finiteNumber(
    retained.identityStrideBytes,
    0
  )));
  const identityBufferByteLength = Math.max(0, Math.round(finiteNumber(
    retained.identityBufferByteLength || retained.identityBuffer?.size,
    retained.identityBuffer?.size ?? 0
  )));
  const identitySchemaAccepted = retained.identitySchema === ULG_SPH_GPU_PARTICLE_IDENTITY_BUFFER_SCHEMA;
  const identityStrideAccepted = identityStrideBytes
    === SPH_GPU_PARTICLE_IDENTITY_UINTS * Uint32Array.BYTES_PER_ELEMENT;
  const identityCapacityAccepted = identityBufferByteLength
    >= outputParticleCapacity * SPH_GPU_PARTICLE_IDENTITY_UINTS * Uint32Array.BYTES_PER_ELEMENT;
  if (identityRequired && !retained.identityBuffer) {
    blockers.push('schroeder-particle-storage-identity-buffer-missing-for-arbitrary-domains');
  }
  if (identityRequired && !particleIdentityMutationApproved) {
    blockers.push('schroeder-particle-storage-identity-mutation-not-admitted');
  }
  if (retained.identityBuffer && !identitySchemaAccepted) {
    blockers.push('schroeder-particle-storage-identity-schema-invalid');
  }
  if (retained.identityBuffer && !identityStrideAccepted) {
    blockers.push('schroeder-particle-storage-identity-stride-invalid');
  }
  if (retained.identityBuffer && !identityCapacityAccepted) {
    blockers.push('schroeder-particle-storage-identity-capacity-incomplete');
  }
  // Capacity is buffer headroom, not live particles. The authoritative count
  // only grows past the source count through an explicitly admitted
  // split/merge count delta; without one, adoption must not claim growth.
  const admittedParticleCountDelta = Math.round(finiteNumber(
    source.admittedParticleCountDelta,
    0
  ));
  const authoritativeParticleCount = Math.min(
    outputParticleCapacity,
    Math.max(0, sourceParticleCount + admittedParticleCountDelta)
  );
  const adopted = blockers.length === 0;
  return {
    schema: ULG_SCHROEDER_PARTICLE_STORAGE_ADOPTION_SCHEMA,
    status: adopted
      ? 'schroeder-particle-storage-adopted'
      : 'schroeder-particle-storage-adoption-blocked',
    sourceSchema: source.schema || null,
    sourceStatus: source.status || null,
    backend: source.backend || 'webgpu',
    adoptionMode: adopted
      ? 'state-manager-admitted-retained-particle-buffer-swap'
      : 'fail-closed-retained-particle-buffer-observation',
    adopted,
    blockers,
    warnings,
    targetStateFamilies,
    requiredTargetStateFamilies: [...requiredTargetStateFamilies],
    targetStateFamiliesAccepted,
    particleStorageMaterializationAdmissionApproved: admitted,
    particleIdentityMutationApproved,
    retainedParticleBuffers,
    stablePhaseCarrierPairsRequired,
    retainedIdentityBuffer: Boolean(retained.identityBuffer),
    identityRequired,
    identityRevision: retained.identityRevision,
    identitySchema: retained.identitySchema,
    identitySchemaAccepted,
    identityStrideAccepted,
    identityCapacityAccepted,
    sourceParticleCount,
    outputParticleCapacity,
    admittedParticleCountDelta,
    authoritativeParticleCount,
    sourceMlsMpmParticleCount: Math.max(0, Math.round(finiteNumber(
      mlsMpmParticleState?.particleCount,
      sourceParticleCount
    ))),
    stateBuffer: retained.stateBuffer,
    thermoBuffer: retained.thermoBuffer,
    mechanicsBuffer: retained.mechanicsBuffer,
    identityBuffer: retained.identityBuffer,
    materializationBuffer: retained.materializationBuffer,
    stateBufferByteLength: retained.stateBufferByteLength,
    thermoBufferByteLength: retained.thermoBufferByteLength,
    mechanicsBufferByteLength: retained.mechanicsBufferByteLength,
    identityBufferByteLength,
    materializationBufferByteLength: retained.materializationBufferByteLength,
    stateStrideBytes: sphParticleState?.stateStrideBytes
      ?? (SPH_GPU_PARTICLE_STATE_FLOATS * Float32Array.BYTES_PER_ELEMENT),
    thermoStrideBytes: sphParticleState?.thermoStrideBytes
      ?? (SPH_GPU_PARTICLE_THERMO_FLOATS * Float32Array.BYTES_PER_ELEMENT),
    mechanicsStrideBytes: mlsMpmParticleState?.mechanicsStrideBytes
      ?? (MLS_MPM_GPU_PARTICLE_MECHANICS_FLOATS * Float32Array.BYTES_PER_ELEMENT),
    identityStrideBytes: identityStrideBytes || (
      SPH_GPU_PARTICLE_IDENTITY_UINTS * Uint32Array.BYTES_PER_ELEMENT
    ),
    renderDomainKeys: retained.renderDomainKeys,
    replacementPolicy: adopted
      ? 'retained-output-buffers-adopted-by-resident-state-authority'
      : (source.replacementPolicy || 'retained-output-buffers-await-state-manager-swap'),
    stateMutationStatus: adopted
      ? 'particle-storage-materialization-adopted-as-next-resident-particle-storage'
      : (source.stateMutationStatus || 'particle-storage-materialization-adoption-blocked'),
    stateAuthorityStatus: adopted
      ? 'resident-state-authority-adopted-particle-storage-materialization'
      : (source.stateAuthorityStatus || 'resident-state-authority-particle-storage-adoption-blocked')
  };
}

function rawGpuBufferTransferDetectedInDescriptor(value, depth = 0) {
  if (!value || typeof value !== 'object' || depth > 8) return false;
  const rawBufferKeys = new Set([
    'buffer',
    'gpuBuffer',
    'stateBuffer',
    'thermoBuffer',
    'mechanicsBuffer',
    'identityBuffer',
    'materializationBuffer',
    'particleStateBuffer',
    'particleThermoBuffer',
    'particleMechanicsBuffer',
    'particleIdentityBuffer',
    'outputStateBuffer',
    'outputThermoBuffer',
    'outputMechanicsBuffer',
    'outputIdentityBuffer'
  ]);
  for (const [key, entry] of Object.entries(value)) {
    if (rawBufferKeys.has(key) && entry && typeof entry === 'object') return true;
    if (entry && typeof entry === 'object' && rawGpuBufferTransferDetectedInDescriptor(entry, depth + 1)) {
      return true;
    }
  }
  return false;
}

function particleStorageRetainedRefDescriptor({
  ref,
  role,
  family,
  byteLength,
  strideBytes,
  particleCount,
  retained
}) {
  return {
    ref,
    role,
    family,
    byteLength: Math.max(0, Math.round(finiteNumber(byteLength, 0))),
    strideBytes: Math.max(0, Math.round(finiteNumber(strideBytes, 0))),
    particleCount: Math.max(0, Math.round(finiteNumber(particleCount, 0))),
    retained: retained === true,
    sourceStage: 'schroeder-particle-storage-materialization',
    transferMode: 'descriptor-only-no-raw-gpubuffer-transfer',
    rawGpuBufferSerialized: false,
    rawGpuBufferTransferable: false
  };
}

export function createSchroederAdoptedParticleStorageDescriptorFromStep(step = null, {
  gpuFence = null,
  stateKey = null,
  source = 'ulg-mls-mpm-resident-step-compute-task',
  taskId = null
} = {}) {
  const adoption = step?.schroederParticleStorageAdoption;
  if (!adoption || adoption.adopted !== true) return null;
  const authoritativeParticleCount = Math.max(0, Math.round(finiteNumber(
    adoption.authoritativeParticleCount ?? step?.nextParticleCount,
    0
  )));
  const outputParticleCapacity = Math.max(authoritativeParticleCount, Math.round(finiteNumber(
    adoption.outputParticleCapacity,
    authoritativeParticleCount
  )));
  const retainedBufferRefs = uniqueNonEmptyStrings([
    'sph-state-buffer',
    'sph-thermo-buffer',
    'mls-mpm-mechanics-buffer',
    adoption.identityBuffer ? 'sph-particle-identity-buffer' : null
  ]);
  const retainedRefs = [
    particleStorageRetainedRefDescriptor({
      ref: 'sph-state-buffer',
      role: 'particle-state',
      family: 'sph-particle-state',
      byteLength: adoption.stateBufferByteLength,
      strideBytes: adoption.stateStrideBytes,
      particleCount: outputParticleCapacity,
      retained: Boolean(adoption.stateBuffer)
    }),
    particleStorageRetainedRefDescriptor({
      ref: 'sph-thermo-buffer',
      role: 'particle-thermo',
      family: 'sph-particle-thermo',
      byteLength: adoption.thermoBufferByteLength,
      strideBytes: adoption.thermoStrideBytes,
      particleCount: outputParticleCapacity,
      retained: Boolean(adoption.thermoBuffer)
    }),
    particleStorageRetainedRefDescriptor({
      ref: 'mls-mpm-mechanics-buffer',
      role: 'particle-mechanics',
      family: 'mls-mpm-particle-mechanics',
      byteLength: adoption.mechanicsBufferByteLength,
      strideBytes: adoption.mechanicsStrideBytes,
      particleCount: outputParticleCapacity,
      retained: Boolean(adoption.mechanicsBuffer)
    }),
    ...(adoption.identityBuffer ? [particleStorageRetainedRefDescriptor({
      ref: 'sph-particle-identity-buffer',
      role: 'particle-identity',
      family: 'sph-particle-identity',
      byteLength: adoption.identityBufferByteLength,
      strideBytes: adoption.identityStrideBytes,
      particleCount: outputParticleCapacity,
      retained: true
    })] : [])
  ];
  const compactFence = compactGpuFenceForStateDelta(gpuFence || step?.gpuFence || step?.gpuFenceReport || null);
  const descriptor = {
    schema: ULG_SCHROEDER_ADOPTED_PARTICLE_STORAGE_DESCRIPTOR_SCHEMA,
    status: 'schroeder-adopted-particle-storage-descriptor-ready',
    ready: true,
    adopted: true,
    source,
    taskId,
    stateKey: stateKey || compactFence?.stateKey || null,
    sourceStage: 'schroeder-particle-storage-materialization',
    sourceSchema: adoption.sourceSchema || null,
    sourceStatus: adoption.sourceStatus || null,
    adoptionSchema: adoption.schema || ULG_SCHROEDER_PARTICLE_STORAGE_ADOPTION_SCHEMA,
    adoptionStatus: adoption.status || null,
    adoptionMode: adoption.adoptionMode || null,
    materializationStatus: step?.schroederParticleStorageMaterializationStatus ?? adoption.sourceStatus ?? null,
    particleStorageMaterializationAdmissionApproved:
      adoption.particleStorageMaterializationAdmissionApproved === true,
    particleIdentityMutationApproved: adoption.particleIdentityMutationApproved === true,
    stateAuthorityStatus: adoption.stateAuthorityStatus || null,
    stateMutationStatus: adoption.stateMutationStatus || null,
    replacementPolicy: adoption.replacementPolicy || null,
    sourceParticleCount: Math.max(0, Math.round(finiteNumber(adoption.sourceParticleCount, 0))),
    sourceMlsMpmParticleCount: Math.max(0, Math.round(finiteNumber(adoption.sourceMlsMpmParticleCount, 0))),
    outputParticleCapacity,
    authoritativeParticleCount,
    targetStateFamilies: uniqueNonEmptyStrings(
      adoption.targetStateFamilies?.length
        ? adoption.targetStateFamilies
        : SCHROEDER_PARTICLE_STORAGE_TARGET_FAMILY_NAMES
    ),
    outputFamilies: uniqueNonEmptyStrings([
      ...SCHROEDER_PARTICLE_STORAGE_TARGET_FAMILY_NAMES,
      adoption.identityBuffer ? 'sph-particle-identity' : null,
      'schroeder-particle-storage'
    ]),
    stateMutationFamilies: uniqueNonEmptyStrings([
      'sph-particle-state',
      'sph-particle-thermo',
      'mls-mpm-particle-mechanics',
      adoption.identityBuffer ? 'sph-particle-identity' : null,
      'schroeder-particle-storage'
    ]),
    retainedBufferRefs,
    retainedBufferRefCount: retainedBufferRefs.length,
    retainedRefs,
    retainedRefCount: retainedRefs.length,
    retainedParticleBuffers: adoption.retainedParticleBuffers === true,
    stateBufferRef: 'sph-state-buffer',
    thermoBufferRef: 'sph-thermo-buffer',
    mechanicsBufferRef: 'mls-mpm-mechanics-buffer',
    identityBufferRef: adoption.identityBuffer ? 'sph-particle-identity-buffer' : null,
    stateBufferRetained: Boolean(adoption.stateBuffer),
    thermoBufferRetained: Boolean(adoption.thermoBuffer),
    mechanicsBufferRetained: Boolean(adoption.mechanicsBuffer),
    identityBufferRetained: Boolean(adoption.identityBuffer),
    identityRequired: adoption.identityRequired === true,
    identityRevision: adoption.identityRevision || null,
    identitySchema: adoption.identitySchema || null,
    renderDomainKeys: { ...(adoption.renderDomainKeys || {}) },
    stateBufferByteLength: Math.max(0, Math.round(finiteNumber(adoption.stateBufferByteLength, 0))),
    thermoBufferByteLength: Math.max(0, Math.round(finiteNumber(adoption.thermoBufferByteLength, 0))),
    mechanicsBufferByteLength: Math.max(0, Math.round(finiteNumber(adoption.mechanicsBufferByteLength, 0))),
    identityBufferByteLength: Math.max(0, Math.round(finiteNumber(adoption.identityBufferByteLength, 0))),
    materializationBufferByteLength: Math.max(0, Math.round(finiteNumber(adoption.materializationBufferByteLength, 0))),
    stateStrideBytes: Math.max(0, Math.round(finiteNumber(adoption.stateStrideBytes, 0))),
    thermoStrideBytes: Math.max(0, Math.round(finiteNumber(adoption.thermoStrideBytes, 0))),
    mechanicsStrideBytes: Math.max(0, Math.round(finiteNumber(adoption.mechanicsStrideBytes, 0))),
    identityStrideBytes: Math.max(0, Math.round(finiteNumber(adoption.identityStrideBytes, 0))),
    sameDeviceHotLoopContinuationReady: true,
    sameDeviceReplayReady: true,
    descriptorOnlyPeerComputeHandoff: true,
    copyMode: 'descriptor-only-no-raw-gpubuffer-transfer',
    sourceMode: 'same-device-retained-particle-buffer-swap-descriptor',
    rawGpuBufferTransferAllowed: false,
    rawGpuBufferTransferDetected: false,
    fullParticleReadbackRequired: false,
    fullParticleReadbackAvoided: true,
    portableSnapshotRequired: true,
    crossPeerReplayReady: false,
    crossPeerReplayStatus: 'descriptor-evidence-ready-cross-peer-requires-portable-materialization',
    crossPeerReplayBlocker:
      'materialized-gpu-buffers-remain-device-local-descriptor-replay-requires-peer-local-materialization-or-portable-snapshot',
    stateManagerAdmissionRequired: true,
    stateManagerAdmissionStatus: 'state-manager-admitted-retained-particle-buffer-swap',
    authoritativeStateMutation: true,
    authoritativeMutation: 'state-manager-admitted-schroeder-particle-storage-swap',
    stateMutationFamily: 'schroeder-particle-storage',
    gpuFence: compactFence,
    gpuFenceSatisfied: compactFence?.fenceSatisfied === true,
    residentBufferLeaseLedgerStatus: step?.residentBufferLeaseLedgerStatus ?? null,
    residentBufferLeaseActiveLeaseCount: step?.residentBufferLeaseActiveLeaseCount ?? 0,
    residentBufferLeaseResourceCount: step?.residentBufferLeaseResourceCount ?? 0,
    residentAuthorityLedgerStatus: step?.residentAuthorityLedgerStatus ?? null,
    warnings: [...(adoption.warnings || [])],
    blockers: [...(adoption.blockers || [])],
    scientificValidation: false,
    sphValidation: false,
    phaseChangeValidation: false,
    fullPhysicsValidation: false
  };
  descriptor.rawGpuBufferTransferDetected = rawGpuBufferTransferDetectedInDescriptor(descriptor);
  if (descriptor.rawGpuBufferTransferDetected) {
    descriptor.status = 'schroeder-adopted-particle-storage-descriptor-blocked';
    descriptor.ready = false;
    descriptor.crossPeerReplayStatus = 'blocked-raw-gpubuffer-transfer-detected';
    descriptor.crossPeerReplayBlocker = 'raw-gpubuffer-transfer-detected';
  }
  return descriptor;
}

function retainedSchroederFarAggregateGasStateDeltaBuffers(schroederFarAggregateGasStateDelta) {
  const source = schroederFarAggregateGasStateDelta?.result || schroederFarAggregateGasStateDelta;
  return {
    gasStateDeltaBuffer: source?.gasStateDeltaBuffer || source?.stateDeltaBuffer || null,
    gasStateDeltaBufferByteLength: source?.gasStateDeltaBufferByteLength
      ?? source?.stateDeltaBufferByteLength
      ?? source?.gasStateDeltaByteLength
      ?? 0,
    gasStateDeltaRowCount: Math.max(0, Math.round(finiteNumber(
      source?.gasStateDeltaRowCount ?? source?.stateDeltaRowCount,
      0
    ))),
    gasStateDeltaStrideFloats: Math.max(0, Math.round(finiteNumber(
      source?.gasStateDeltaStrideFloats ?? source?.stateDeltaStrideFloats,
      SCHROEDER_FAR_AGGREGATE_GAS_STATE_DELTA_FLOATS
    ))),
    targetStateFamily: source?.targetStateFamily ?? null,
    pressureInterfaceImportRequired: source?.pressureInterfaceImportRequired === true,
    destroyGasStateDeltaBuffer: source?.destroyGasStateDeltaBuffer || source?.destroyStateDeltaBuffer || null
  };
}

function retainedSchroederFarAggregateGasCellImportBuffers(schroederFarAggregateGasCellImport) {
  const source = schroederFarAggregateGasCellImport?.result || schroederFarAggregateGasCellImport;
  return {
    gasPressureCellsBuffer:
      source?.gasPressureCellsBuffer || source?.pressureInterfaceGasPressureCellsBuffer || null,
    gasPressureCellRowByteLength:
      source?.pressureInterfaceGasPressureCellRowByteLength
      ?? source?.gasPressureCellRowByteLength
      ?? source?.gasPressureCellRowsBufferByteLength
      ?? 0,
    gasPressureCellRowCount: Math.max(0, Math.round(finiteNumber(
      source?.pressureInterfaceGasPressureCellRowCount ?? source?.gasPressureCellRowCount,
      0
    ))),
    gasPressureCellRowStrideFloats: Math.max(0, Math.round(finiteNumber(
      source?.pressureInterfaceGasPressureCellRowStrideFloats ?? source?.gasPressureCellRowStrideFloats,
      SCHROEDER_FAR_AGGREGATE_GAS_CELL_IMPORT_FLOATS
    ))),
    pressureFieldMode: source?.pressureFieldMode ?? null,
    pressureFieldResolution: source?.pressureFieldResolution ?? null,
    pressureInterfaceImportReady: source?.pressureInterfaceImportReady === true,
    retainedGasCellFieldSourceReady: source?.retainedGasCellFieldSourceReady === true,
    retainedGasPressureBufferRefs: [...(source?.retainedGasPressureBufferRefs || [])],
    localPressureGradientReady: source?.localPressureGradientReady === true,
    localPressureGradientStatus: source?.localPressureGradientStatus ?? null,
    destroyGasPressureCellsBuffer: source?.destroyGasPressureCellsBuffer || null
  };
}

function thermalPhaseTransitionDiagnostics(thermalStep) {
  const source = thermalStep?.result || thermalStep;
  if (!source) {
    return {
      thermalPhaseTransitionStatus: null,
      thermalPhaseTransitionCount: 0,
      thermalPhaseTransitionRowsRetained: false
    };
  }
  const explicitCount = Number(source.phaseTransitionCount ?? source.phaseChangeCount);
  const phaseTransitions = Array.isArray(source.phaseTransitions) ? source.phaseTransitions : [];
  const count = Number.isFinite(explicitCount)
    ? Math.max(0, Math.round(explicitCount))
    : phaseTransitions.length;
  const status = source.thermalPhaseTransitionStatus
    || source.phaseTransitionStatus
    || source.phaseChangeStatus
    || (count > 0 ? 'thermal-phase-transition-detected' : 'thermal-phase-transition-not-detected');
  return {
    thermalPhaseTransitionStatus: status,
    thermalPhaseTransitionCount: count,
    thermalPhaseTransitionRowsRetained: Boolean(source.stateBuffer && source.thermoBuffer),
    thermalPhaseTransitionSourcePhaseId: source.phaseTransitionSourcePhaseId ?? source.sourcePhaseId ?? null,
    thermalPhaseTransitionNextPhaseId: source.phaseTransitionNextPhaseId ?? source.nextPhaseId ?? null
  };
}

function estimatedPackedBytes(source, {
  valuesKey,
  byteLengthKey,
  strideBytesKey,
  count,
  fallbackStrideFloats
} = {}) {
  const explicitByteLength = finiteNumber(source?.[byteLengthKey] ?? source?.[valuesKey]?.byteLength, -1);
  if (explicitByteLength >= 0) return Math.max(0, Math.round(explicitByteLength));
  const strideBytes = finiteNumber(
    source?.[strideBytesKey],
    fallbackStrideFloats * Float32Array.BYTES_PER_ELEMENT
  );
  return Math.max(0, Math.round(count * Math.max(0, strideBytes)));
}

function estimateResidentGpuLaneCopyBudget({
  sphParticleState,
  mlsMpmParticleState,
  sphParticleUpload = null,
  mlsMpmParticleUpload = null,
  readbackMode = FULL_READBACK_MODE
} = {}) {
  const sphCount = Math.max(0, Math.round(finiteNumber(sphParticleState?.particleCount, 0)));
  const mlsCount = Math.max(0, Math.round(finiteNumber(mlsMpmParticleState?.particleCount, sphCount)));
  const sphStateBytes = estimatedPackedBytes(sphParticleState, {
    valuesKey: 'state',
    byteLengthKey: 'stateBufferByteLength',
    strideBytesKey: 'stateStrideBytes',
    count: sphCount,
    fallbackStrideFloats: SPH_GPU_PARTICLE_STATE_FLOATS
  });
  const sphThermoBytes = estimatedPackedBytes(sphParticleState, {
    valuesKey: 'thermo',
    byteLengthKey: 'thermoBufferByteLength',
    strideBytesKey: 'thermoStrideBytes',
    count: sphCount,
    fallbackStrideFloats: SPH_GPU_PARTICLE_THERMO_FLOATS
  });
  const mechanicsBytes = estimatedPackedBytes(mlsMpmParticleState, {
    valuesKey: 'mechanics',
    byteLengthKey: 'mechanicsBufferByteLength',
    strideBytesKey: 'mechanicsStrideBytes',
    count: mlsCount,
    fallbackStrideFloats: MLS_MPM_GPU_PARTICLE_MECHANICS_FLOATS
  });
  const uploadBytes = (sphParticleUpload?.status === 'webgpu-uploaded' ? 0 : (sphStateBytes + sphThermoBytes))
    + (mlsMpmParticleUpload?.status === 'webgpu-uploaded' ? 0 : mechanicsBytes);
  const compactSummaryBytes = readbackMode === NO_FULL_READBACK_MODE ? COMPACT_SUMMARY_READBACK_BYTES : 0;
  return {
    schema: 'peercompute.compute.gpu-resident-lane-copy-budget.v0',
    uploadBytes,
    readbackBytes: readbackMode === NO_FULL_READBACK_MODE ? compactSummaryBytes : (sphStateBytes + sphThermoBytes + mechanicsBytes),
    retainedBytes: sphStateBytes + sphThermoBytes + mechanicsBytes,
    compactSummaryBytes,
    fullReadbackReason: readbackMode === NO_FULL_READBACK_MODE ? null : 'resident-step-full-readback-mode'
  };
}

function acquireResidentGpuLaneLease(manager, spec) {
  if (!manager) return null;
  if (typeof manager.acquireGpuResidentLaneLease === 'function') return manager.acquireGpuResidentLaneLease(spec);
  if (typeof manager.acquireLease === 'function') return manager.acquireLease(spec);
  throw new Error('GPU resident lane manager must expose acquireGpuResidentLaneLease() or acquireLease()');
}

function completeResidentGpuLaneLease(manager, leaseId, options) {
  if (!manager || !leaseId) return null;
  if (typeof manager.completeGpuResidentLaneLease === 'function') return manager.completeGpuResidentLaneLease(leaseId, options);
  if (typeof manager.completeLease === 'function') return manager.completeLease(leaseId, options);
  throw new Error('GPU resident lane manager must expose completeGpuResidentLaneLease() or completeLease()');
}

function rejectResidentGpuLaneLease(manager, leaseId, reason) {
  if (!manager || !leaseId) return null;
  if (typeof manager.rejectGpuResidentLaneLease === 'function') return manager.rejectGpuResidentLaneLease(leaseId, reason);
  if (typeof manager.rejectLease === 'function') return manager.rejectLease(leaseId, reason);
  return null;
}

function queueEvidenceFromResidentStep(step) {
  const computeTaskQueueFence = step?.computeTaskQueueFence ?? null;
  if (
    computeTaskQueueFence?.status === 'queue-work-completed'
    && computeTaskQueueFence?.method === 'queue.onSubmittedWorkDone'
    && computeTaskQueueFence?.completed === true
    && computeTaskQueueFence?.fenceSatisfied === true
  ) {
    return {
      ...computeTaskQueueFence,
      satisfactionReason: computeTaskQueueFence.satisfactionReason
        || 'compute-task-observed-real-queue-completion'
    };
  }
  const fusedQueueFenceStatus =
    step?.fusedResidentSequence?.queueFenceStatus
    ?? step?.stageTiming?.queueFenceStatus?.fusedMechanicsSequence
    ?? null;
  const fusedQueueFenceMethod =
    step?.fusedResidentSequence?.queueFenceMethod
    ?? step?.stageTiming?.queueFenceMethod?.fusedMechanicsSequence
    ?? null;
  if (fusedQueueFenceStatus === 'complete') {
    return {
      status: 'queue-work-completed',
      method: fusedQueueFenceMethod || 'queue.onSubmittedWorkDone',
      fenceSatisfied: true,
      satisfactionReason: 'fused-resident-mechanics-sequence-queue-fence-completed'
    };
  }
  const candidates = [
    step?.compactGpuSummary,
    step?.residentProductMass,
    step?.reactionStep?.result || step?.reactionStep,
    step?.mechanicsRefreshStep?.result || step?.mechanicsRefreshStep,
    step?.thermalStep?.result || step?.thermalStep,
    step?.schroederParticleStorageMaterialization?.result || step?.schroederParticleStorageMaterialization,
    step?.g2pReconstruction,
    step?.gridUpdate,
    step?.p2gGridProjection
  ];
  let firstQueueEvidence = null;
  for (const candidate of candidates) {
    const status = candidate?.queueCompletionStatus
      ?? candidate?.productEventMergeQueueCompletionStatus
      ?? candidate?.gpuResult?.queueCompletionStatus
      ?? null;
    const method = candidate?.queueCompletionMethod
      ?? candidate?.productEventMergeQueueCompletionMethod
      ?? candidate?.gpuResult?.queueCompletionMethod
      ?? null;
    if (status || method) {
      const resolvedStatus = status || 'queue-submitted-status-unspecified';
      const resolvedMethod = method || null;
      const evidence = {
        status: resolvedStatus,
        method: resolvedMethod,
        fenceSatisfied: false
      };
      if (!firstQueueEvidence) firstQueueEvidence = evidence;
      if (residentStepFenceSatisfied(resolvedStatus, resolvedMethod)) return evidence;
    }
  }
  if (firstQueueEvidence) return firstQueueEvidence;
  if (step?.backend === 'webgpu') {
    return {
      status: 'queue-completion-evidence-unavailable',
      method: step.readbackMode === NO_FULL_READBACK_MODE
        ? 'resident-step-retained-webgpu-chain'
        : 'resident-step-webgpu-readback-evidence-missing',
      fenceSatisfied: false
    };
  }
  return { status: 'gpu-fence-not-submitted', method: null };
}

async function awaitResidentComputeTaskQueueFence(execution, requirement, device) {
  const step = execution?.finalStep || execution;
  if (!step || typeof step !== 'object') return null;
  if (requirement?.required === false) {
    step.computeTaskQueueFence = {
      status: 'gpu-fence-not-required',
      method: null,
      completed: false,
      fenceSatisfied: false
    };
    return step.computeTaskQueueFence;
  }

  const existingEvidence = queueEvidenceFromResidentStep(step);
  const existingCompletionIsValid = (
    existingEvidence.status === 'queue-work-completed'
    && existingEvidence.method === 'queue.onSubmittedWorkDone'
  ) || existingEvidence.status === 'readback-map-completed';
  if (existingCompletionIsValid) {
    step.computeTaskQueueFence = {
      ...existingEvidence,
      completed: true,
      fenceSatisfied: true,
      satisfactionReason: existingEvidence.satisfactionReason
        || 'resident-step-reported-explicit-queue-completion'
    };
    return step.computeTaskQueueFence;
  }

  if (typeof device?.queue?.onSubmittedWorkDone !== 'function') {
    step.computeTaskQueueFence = {
      status: 'queue-completion-observer-unavailable',
      method: null,
      completed: false,
      fenceSatisfied: false
    };
    return step.computeTaskQueueFence;
  }
  try {
    await device.queue.onSubmittedWorkDone();
    step.computeTaskQueueFence = {
      status: 'queue-work-completed',
      method: 'queue.onSubmittedWorkDone',
      completed: true,
      fenceSatisfied: true,
      satisfactionReason: 'compute-task-observed-real-queue-completion'
    };
  } catch (error) {
    step.computeTaskQueueFence = {
      status: 'queue-completion-observer-rejected',
      method: 'queue.onSubmittedWorkDone',
      completed: false,
      fenceSatisfied: false,
      reason: error instanceof Error ? error.message : String(error)
    };
  }
  return step.computeTaskQueueFence;
}

function retainedBufferRefsFromResidentStep(step) {
  const refs = [];
  if (step?.p2gGridProjection?.gpuResult?.gridBuffer || step?.p2gGridProjection?.gridBuffer) refs.push('p2g-grid-buffer');
  if (step?.gridUpdate?.gpuResult?.updatedGridBuffer || step?.gridUpdate?.updatedGridBuffer) refs.push('updated-grid-buffer');
  if (step?.nextParticleUploads?.sphParticleUpload?.stateBuffer) refs.push('sph-state-buffer');
  if (step?.nextParticleUploads?.sphParticleUpload?.thermoBuffer) refs.push('sph-thermo-buffer');
  if (step?.nextParticleUploads?.sphParticleUpload?.identityBuffer) refs.push('sph-particle-identity-buffer');
  if (step?.nextParticleUploads?.mlsMpmParticleUpload?.mechanicsBuffer) refs.push('mls-mpm-mechanics-buffer');
  if (step?.residentProductMass?.productEventBufferRetained) refs.push('resident-product-mass-buffer');
  if (step?.schroederFarAggregateGasCellImportBufferRetained) refs.push('resident-gas-pressure-cells-buffer');
  if (step?.compactGpuSummary?.compactSummaryBufferAuthority) refs.push('compact-summary-diagnostics');
  return [...new Set(refs)];
}

function residentStepFenceSatisfied(status, method = null) {
  const normalizedStatus = String(status || '');
  if (normalizedStatus === 'queue-work-completed') {
    return method === 'queue.onSubmittedWorkDone';
  }
  return [
    'gpu-fence-completed',
    'readback-map-completed'
  ].includes(normalizedStatus);
}

export function createMlsMpmResidentStepGpuFenceReport(step, requirement = {}) {
  const queueEvidence = queueEvidenceFromResidentStep(step);
  const status = queueEvidence.status || 'gpu-fence-report-missing';
  const method = queueEvidence.method || null;
  const retainedBufferRefs = retainedBufferRefsFromResidentStep(step);
  const fenceSatisfied = queueEvidence.fenceSatisfied === true
    || residentStepFenceSatisfied(status, method);
  return {
    schema: PEERCOMPUTE_GPU_FENCE_REPORT_SCHEMA,
    status,
    method,
    fenceSatisfied,
    required: requirement?.required !== false,
    laneId: requirement?.laneId || requirement?.gpuLaneId || null,
    stateKey: requirement?.stateKey || requirement?.gpuStateKey || null,
    queueFencePolicy: requirement?.queueFencePolicy || requirement?.fencePolicy || 'queue.onSubmittedWorkDone-before-admission',
    queueCompletionStatus: status,
    queueCompletionMethod: method,
    retainedBufferRefs,
    source: 'ulg-mls-mpm-resident-step-compute-task',
    backend: step?.backend || null,
    readbackMode: step?.readbackMode || null,
    satisfactionReason: queueEvidence.satisfactionReason || null,
    step: step?.step ?? null,
    sequence: step?.sequence ?? null
  };
}

function compactGpuFenceForStateDelta(gpuFence = null) {
  if (!gpuFence || typeof gpuFence !== 'object') return null;
  return {
    schema: gpuFence.schema || PEERCOMPUTE_GPU_FENCE_REPORT_SCHEMA,
    status: gpuFence.status || null,
    method: gpuFence.method || null,
    fenceSatisfied: gpuFence.fenceSatisfied === true,
    required: gpuFence.required === true,
    laneId: gpuFence.laneId || gpuFence.gpuLaneId || null,
    stateKey: gpuFence.stateKey || gpuFence.gpuStateKey || null,
    queueFencePolicy: gpuFence.queueFencePolicy || gpuFence.fencePolicy || null,
    queueCompletionStatus: gpuFence.queueCompletionStatus || null,
    queueCompletionMethod: gpuFence.queueCompletionMethod || null,
    retainedBufferRefs: [...(gpuFence.retainedBufferRefs || [])],
    source: gpuFence.source || null
  };
}

function compactResidentStepSummaryForStateDelta(summary = null) {
  if (!summary || typeof summary !== 'object') return null;
  return {
    schema: summary.schema || 'peercompute.ulg.mls-mpm-resident-step-sequence-summary.v0',
    stepIndex: summary.stepIndex ?? null,
    backend: summary.backend ?? null,
    status: summary.status ?? null,
    readbackMode: summary.readbackMode ?? null,
    normalHotLoopReadbackFree: summary.normalHotLoopReadbackFree === true,
    gpuAuthoritativeState: summary.gpuAuthoritativeState === true,
    renderStateReadbackAvailable: summary.renderStateReadbackAvailable === true,
    compactSummaryAuthority: summary.compactSummaryAuthority ?? null,
    compactSummaryAdmissionStatus: summary.compactSummaryAdmissionStatus ?? null,
    compactSummaryAuthoritativeMutation: summary.compactSummaryAuthoritativeMutation === true,
    schroederParticleStorageAdoptionStatus: summary.schroederParticleStorageAdoptionStatus ?? null,
    schroederParticleStorageAdopted: summary.schroederParticleStorageAdopted === true,
    schroederParticleStorageAdoptionMode: summary.schroederParticleStorageAdoptionMode ?? null,
    schroederParticleStorageAuthoritativeParticleCount:
      summary.schroederParticleStorageAuthoritativeParticleCount ?? null,
    schroederParticleStorageMaterializationStatus:
      summary.schroederParticleStorageMaterializationStatus ?? null,
    nextParticleCount: summary.nextParticleCount ?? null,
    diagnostics: summary.diagnostics && typeof summary.diagnostics === 'object'
      ? {
          particleCount: summary.diagnostics.particleCount ?? null,
          sourceMassKg: summary.diagnostics.sourceMassKg ?? null,
          nextMassKg: summary.diagnostics.nextMassKg ?? null,
          massDeltaKg: summary.diagnostics.massDeltaKg ?? null,
          maxDisplacementM: summary.diagnostics.maxDisplacementM ?? null,
          maxSpeedMPerS: summary.diagnostics.maxSpeedMPerS ?? null,
          reactionResidentProductMassStatus: summary.diagnostics.reactionResidentProductMassStatus ?? null,
          pressureInterfaceForceApplicationStatus: summary.diagnostics.pressureInterfaceForceApplicationStatus ?? null,
          residentAuthorityLedgerStatus: summary.diagnostics.residentAuthorityLedgerStatus ?? null,
          residentAuthorityWarnings: [...(summary.diagnostics.residentAuthorityWarnings || [])],
          residentAuthorityBlockers: [...(summary.diagnostics.residentAuthorityBlockers || [])],
          residentBufferLeaseLedgerStatus: summary.diagnostics.residentBufferLeaseLedgerStatus ?? null,
          gpuResidentLaneFenceSatisfied: summary.diagnostics.gpuResidentLaneFenceSatisfied === true
        }
      : null
  };
}

export function createMlsMpmResidentStepsCommitDelta(execution = {}, {
  taskId = null,
  scope = 'ulg-sph-resident-pass-dag',
  stateKey = null,
  lawGraphNode = null,
  outputFamilies = [],
  gpuResidentLane = null,
  residentSequenceLaneContract = null
} = {}) {
  const stepSummaries = Array.isArray(execution?.stepSummaries) ? execution.stepSummaries : [];
  const finalStepSummary = stepSummaries.length
    ? stepSummaries[stepSummaries.length - 1]
    : summarizeResidentStepForSequence(execution?.finalStep || execution, Math.max(0, stepSummaries.length - 1));
  const gpuFence = compactGpuFenceForStateDelta(execution?.gpuFence || execution?.gpuFenceReport || null);
  const resolvedStateKey = stateKey || gpuFence?.stateKey || gpuResidentLane?.stateKey || null;
  const schroederAdoptedParticleStorageDescriptor =
    execution?.schroederAdoptedParticleStorageDescriptor
    || createSchroederAdoptedParticleStorageDescriptorFromStep(execution?.finalStep || execution, {
      gpuFence,
      stateKey: resolvedStateKey,
      source: 'ulg-mls-mpm-resident-steps-state-delta',
      taskId
    });
  const completedStepCount = Math.max(0, Math.round(finiteNumber(execution?.completedStepCount, stepSummaries.length)));
  const version = Math.max(
    0,
    Math.round(finiteNumber(
      execution?.finalStep?.step
        ?? execution?.finalStep?.sequence
        ?? finalStepSummary?.stepIndex
        ?? completedStepCount,
      completedStepCount
    ))
  );
  return {
    schema: ULG_MLS_MPM_RESIDENT_STEPS_COMMIT_DELTA_SCHEMA,
    taskId: taskId || `ulg:sph-resident-steps:${resolvedStateKey || 'local'}`,
    scope,
    version,
    timestamp: Date.now(),
    payload: {
      schema: ULG_MLS_MPM_RESIDENT_STEPS_STATE_DELTA_SCHEMA,
      status: execution?.status || 'resident-steps-delta-ready',
      stateKey: resolvedStateKey,
      backend: execution?.backend || null,
      readbackMode: execution?.readbackMode || execution?.finalStep?.readbackMode || null,
      requestedReadbackMode: execution?.requestedReadbackMode || null,
      completedStepCount,
      continuationAvailable: execution?.continuationAvailable === true,
      continuedFromResidentState: execution?.continuedFromResidentState === true,
      residentSourceMode: execution?.residentSourceMode || null,
      lawGraphNode: lawGraphNode || execution?.lawGraphNode || null,
      outputFamilies: [...(outputFamilies || [])],
      gpuFence,
      retainedBufferRefs: [...(gpuFence?.retainedBufferRefs || [])],
      schroederAdoptedParticleStorageDescriptor,
      schroederParticleStorageContinuationAvailable:
        schroederAdoptedParticleStorageDescriptor?.ready === true,
      schroederParticleStorageStateManagerAdmissionRequired:
        schroederAdoptedParticleStorageDescriptor?.stateManagerAdmissionRequired === true,
      schroederParticleStorageRawGpuBufferTransferDetected:
        schroederAdoptedParticleStorageDescriptor?.rawGpuBufferTransferDetected === true,
      gpuResidentLaneRequirement: gpuResidentLane || execution?.gpuResidentLaneRequirement || null,
      residentSequenceLaneContract: residentSequenceLaneContract || execution?.residentSequenceLaneContract || null,
      finalStep: compactResidentStepSummaryForStateDelta(finalStepSummary),
      stepSummaries: stepSummaries.slice(-4).map((summary) => compactResidentStepSummaryForStateDelta(summary)),
      normalHotLoopReadbackFree: execution?.finalStep?.normalHotLoopReadbackFree === true,
      gpuAuthoritativeState: execution?.finalStep?.gpuAuthoritativeState === true,
      scientificValidation: false,
      sphValidation: false,
      phaseChangeValidation: false,
      fullPhysicsValidation: false
    }
  };
}

function attachResidentGpuLaneExecution(step, { lease = null, execution = null, error = null } = {}) {
  const gpuFence = execution?.gpuFence || execution?.lease?.gpuFence || null;
  step.gpuResidentLane = {
    schema: ULG_MLS_MPM_RESIDENT_GPU_LANE_ADAPTER_SCHEMA,
    status: error ? 'gpu-resident-lane-error' : (execution ? 'gpu-resident-lane-completed' : (lease ? 'gpu-resident-lane-lease-active' : 'gpu-resident-lane-not-configured')),
    lease,
    execution,
    gpuFence,
    error: error ? (error instanceof Error ? error.message : String(error)) : null
  };
  step.gpuResidentLaneStatus = step.gpuResidentLane.status;
  step.gpuResidentLaneLeaseId = lease?.leaseId || execution?.lease?.leaseId || null;
  step.gpuResidentLaneFenceStatus = gpuFence?.status || null;
  step.gpuResidentLaneFenceSatisfied = gpuFence?.fenceSatisfied === true;
  step.gpuResidentLaneRetainedBufferRefs = [...(gpuFence?.retainedBufferRefs || lease?.retainedBufferRefs || [])];
  if (step.diagnostics) {
    step.diagnostics.gpuResidentLaneStatus = step.gpuResidentLaneStatus;
    step.diagnostics.gpuResidentLaneLeaseId = step.gpuResidentLaneLeaseId;
    step.diagnostics.gpuResidentLaneFenceStatus = step.gpuResidentLaneFenceStatus;
    step.diagnostics.gpuResidentLaneFenceSatisfied = step.gpuResidentLaneFenceSatisfied;
    step.diagnostics.gpuResidentLaneRetainedBufferRefCount = step.gpuResidentLaneRetainedBufferRefs.length;
  }
  return step;
}

function computeResidentLaneTaskCopyBudget({
  sphParticleState,
  mlsMpmParticleState,
  sphParticleUpload = null,
  mlsMpmParticleUpload = null,
  readbackMode = FULL_READBACK_MODE,
  gpuResidentLaneCopyBudget = null,
  copyBudget = null
} = {}) {
  if (copyBudget && typeof copyBudget === 'object') return { ...copyBudget };
  if (gpuResidentLaneCopyBudget && typeof gpuResidentLaneCopyBudget === 'object') return { ...gpuResidentLaneCopyBudget };
  return estimateResidentGpuLaneCopyBudget({
    sphParticleState,
    mlsMpmParticleState,
    sphParticleUpload,
    mlsMpmParticleUpload,
    readbackMode
  });
}

export function summarizeMlsMpmResidentHotLoopBudget({
  sphParticleState,
  mlsMpmParticleState,
  sphParticleUpload = null,
  mlsMpmParticleUpload = null,
  readbackMode = FULL_READBACK_MODE,
  stepCount = 1,
  compactSummaryMode = MLS_MPM_RESIDENT_COMPACT_SUMMARY_MODE_EVERY_STEP,
  activeGridDispatchPolicy = null,
  gpuResidentLaneCopyBudget = null,
  copyBudget = null
} = {}) {
  const normalizedReadbackMode = readbackMode === NO_FULL_READBACK_MODE
    ? NO_FULL_READBACK_MODE
    : FULL_READBACK_MODE;
  const normalizedStepCount = Math.max(1, Math.round(finiteNumber(stepCount, 1)));
  const normalizedCompactSummaryMode = normalizeMlsMpmResidentCompactSummaryMode(compactSummaryMode);
  const summarizedStepCount = compactSummaryStepCountForMode({
    readbackMode: normalizedReadbackMode,
    compactSummaryMode: normalizedCompactSummaryMode,
    stepCount: normalizedStepCount
  });
  const singleStepCopyBudget = computeResidentLaneTaskCopyBudget({
    sphParticleState,
    mlsMpmParticleState,
    sphParticleUpload,
    mlsMpmParticleUpload,
    readbackMode: normalizedReadbackMode,
    gpuResidentLaneCopyBudget,
    copyBudget
  });
  const normalizedCopyBudget = normalizedReadbackMode === NO_FULL_READBACK_MODE
    ? {
        ...singleStepCopyBudget,
        readbackBytes: COMPACT_SUMMARY_READBACK_BYTES * summarizedStepCount,
        compactSummaryBytes: COMPACT_SUMMARY_READBACK_BYTES * summarizedStepCount
      }
    : {
        ...singleStepCopyBudget,
        readbackBytes: singleStepCopyBudget.readbackBytes * normalizedStepCount
      };
  const activeGridEnabled = activeGridDispatchPolicy?.enabled === true;
  const noFullReadback = normalizedReadbackMode === NO_FULL_READBACK_MODE;
  const noSummaryReadback = noFullReadback
    && !compactSummaryModeRequestsReadback(normalizedCompactSummaryMode);
  const activeGridPlanOnlySummary = noFullReadback
    && normalizedCompactSummaryMode === MLS_MPM_RESIDENT_COMPACT_SUMMARY_MODE_PLAN_ONLY;
  const status = noFullReadback
    ? (noSummaryReadback
        ? (activeGridPlanOnlySummary
            ? 'webgpu-ocean-hot-loop-active-grid-plan-only-budget'
            : 'webgpu-ocean-hot-loop-no-readback-budget')
        : 'webgpu-ocean-hot-loop-compact-summary-budget')
    : 'full-readback-transition-budget';
  return {
    schema: ULG_MLS_MPM_WEBGPU_OCEAN_HOT_LOOP_BUDGET_SCHEMA,
    status,
    readbackMode: normalizedReadbackMode,
    stepCount: normalizedStepCount,
    compactSummaryMode: normalizedCompactSummaryMode,
    compactSummaryStepCount: summarizedStepCount,
    normalHotLoopReadbackFree: noFullReadback,
    noSummaryReadback,
    activeGridPlanOnlySummary,
    activeGridEnabled,
    activeGridDispatchPolicyStatus: activeGridDispatchPolicy?.promotionStatus || null,
    activeGridDispatchPlanRefreshMode:
      activeGridDispatchPolicy?.activeGridDispatchPlanRefreshMode || null,
    activeGridDispatchPlanFinalOnly:
      activeGridDispatchPolicy?.activeGridDispatchPlanRefreshMode === MLS_MPM_ACTIVE_GRID_PLAN_REFRESH_MODE_FINAL_ONLY,
    uploadBytes: normalizedCopyBudget.uploadBytes ?? 0,
    readbackBytes: normalizedCopyBudget.readbackBytes ?? 0,
    retainedBytes: normalizedCopyBudget.retainedBytes ?? 0,
    compactSummaryBytes: normalizedCopyBudget.compactSummaryBytes ?? 0,
    fullReadbackReason: normalizedCopyBudget.fullReadbackReason ?? null,
    singleStepCopyBudget,
    copyBudget: normalizedCopyBudget
  };
}

function createResidentLawGraphNodeTaskRef({
  graphId = 'peercompute.ulg.local-sph-law-closure-graph',
  graphSchema = 'peercompute.ulg.law-closure-graph.v0',
  nodeId = 'ulg-mls-mpm-sph-resident-step',
  solverId = 'ulg-mls-mpm-sph-resident-step',
  runtimeTarget = 'webgpu-resident-lane',
  readFamilies = [],
  writeFamilies = [],
  requiredClosures = [
    'mechanics-material-table',
    'thermal-material-table',
    'thermal-response-graph',
    'reaction-table',
    'pressure-interface-force-rows'
  ],
  validationGates = [
    'resident-authority-ledger',
    'gpu-fence-report',
    'copy-budget',
    'compact-summary'
  ],
  cachePolicy = 'hot-gpu-lane-with-warm-closure-tables'
} = {}) {
  return {
    schema: ULG_LAW_GRAPH_NODE_TASK_REF_SCHEMA,
    graphSchema,
    graphId,
    nodeId,
    solverId,
    runtimeTarget,
    readFamilies: [...readFamilies],
    writeFamilies: [...writeFamilies],
    requiredClosures: [...requiredClosures],
    validationGates: [...validationGates],
    cachePolicy,
    scientificValidation: false,
    sphValidation: false,
    phaseChangeValidation: false,
    fullPhysicsValidation: false
  };
}

function createResidentGpuFenceRequirement({
  laneId,
  stateKey,
  queueFencePolicy,
  retainedBufferRefs,
  source,
  required = true
}) {
  return {
    schema: PEERCOMPUTE_GPU_FENCE_REQUIREMENT_SCHEMA,
    required: required !== false,
    laneId,
    stateKey,
    queueFencePolicy,
    retainedBufferRefs: [...retainedBufferRefs],
    source
  };
}

function createResidentActiveGridDispatchPolicy({
  requested = false,
  fusedResidentSequence = false,
  stepCount = 1,
  readbackMode = FULL_READBACK_MODE,
  compactSummaryMode = MLS_MPM_RESIDENT_COMPACT_SUMMARY_MODE_EVERY_STEP,
  activeGridDispatchPlanRefreshMode = MLS_MPM_ACTIVE_GRID_PLAN_REFRESH_MODE_EVERY_STEP,
  safetyCells = DEFAULT_FUSED_ACTIVE_GRID_SAFETY_CELLS
} = {}) {
  const normalizedCompactSummaryMode = normalizeMlsMpmResidentCompactSummaryMode(compactSummaryMode);
  const normalizedActiveGridDispatchPlanRefreshMode = normalizeMlsMpmActiveGridPlanRefreshMode(
    activeGridDispatchPlanRefreshMode
  );
  const activeRequested = requested === true;
  const sequenceRequested = fusedResidentSequence === true;
  const enabled = activeRequested && sequenceRequested;
  return {
    schema: ULG_MLS_MPM_ACTIVE_GRID_DISPATCH_POLICY_SCHEMA,
    enabled,
    mode: enabled ? 'fused-resident-sequence-active-grid-aabb' : 'full-grid-dispatch',
    requested: activeRequested,
    fusedResidentSequenceRequested: sequenceRequested,
    stepCount,
    readbackMode,
    compactSummaryMode: normalizedCompactSummaryMode,
    activeGridDispatchPlanRefreshMode: normalizedActiveGridDispatchPlanRefreshMode,
    safetyCells: enabled
      ? Math.max(1, Math.round(finiteNumber(
          safetyCells == null ? DEFAULT_FUSED_ACTIVE_GRID_SAFETY_CELLS : safetyCells,
          DEFAULT_FUSED_ACTIVE_GRID_SAFETY_CELLS
        )))
      : 0,
    requiresNoFullReadback: enabled,
    requiresFinalOnlyCompactSummary: enabled,
    allowsFinalOnlyActiveGridPlanRefresh:
      normalizedActiveGridDispatchPlanRefreshMode === MLS_MPM_ACTIVE_GRID_PLAN_REFRESH_MODE_FINAL_ONLY,
    requiresFusedResidentSequence: activeRequested,
    requiresTrustworthyPositionBounds: enabled,
    requiresGridClearBeforeG2p: enabled,
    retainedGridLayout: 'full-grid-row-layout',
    authority: 'compute-manager-gpu-resident-lane-policy',
    promotionStatus: enabled
      ? 'opt-in-validation-required'
      : (activeRequested ? 'blocked-fused-resident-sequence-not-requested' : 'not-requested')
  };
}

function fusedResidentSequenceSidecarBlockers({
  thermalMaterialTable = null,
  reactionTable = null,
  pressureInterfaceForceRowsBuffer = null,
  pressureInterfaceForceSolver = null,
  residentProductMass = null,
  phaseCarrierPlan = null
} = {}) {
  const blockers = [];
  if (thermalMaterialTable) blockers.push('thermal-sidecar');
  if (finiteNumber(reactionTable?.reactionCount, 0) > 0) blockers.push('reaction-sidecar');
  if (pressureInterfaceForceRowsBuffer) blockers.push('pressure-interface-force-rows');
  if (pressureInterfaceForceSolver) blockers.push('pressure-interface-force-solver');
  if (residentProductMass) blockers.push('resident-product-mass-sidecar');
  if (phaseCarrierPlanReady(phaseCarrierPlan)) {
    blockers.push('phase-carrier-transfer-sidecar');
  }
  return blockers;
}

function uniqueStringList(values = []) {
  return [...new Set(values.filter((value) => typeof value === 'string' && value.trim()).map((value) => value.trim()))];
}

function createFusedResidentSidecarFusionPlan({
  requested = false,
  stepCount = 1,
  readbackMode = FULL_READBACK_MODE,
  compactSummaryMode = MLS_MPM_RESIDENT_COMPACT_SUMMARY_MODE_EVERY_STEP,
  activeGridRequested = false,
  sidecarBlockers = [],
  thermalSidecarFusionAvailable = false
} = {}) {
  const normalizedSidecarBlockers = uniqueStringList(sidecarBlockers);
  const sidecarFusionRequired = requested === true && normalizedSidecarBlockers.length > 0;
  const thermalSidecarFusionRunnable = Boolean(
    sidecarFusionRequired
    && thermalSidecarFusionAvailable === true
    && normalizedSidecarBlockers.length === 1
    && normalizedSidecarBlockers[0] === 'thermal-sidecar'
  );
  const stages = [];
  const addStage = (stage) => {
    if (!stage || stages.some((entry) => entry.id === stage.id)) return;
    stages.push({
      runtimeTarget: 'webgpu-resident-lane',
      implementedInCurrentFusedSequence: false,
      ...stage
    });
  };

  if (normalizedSidecarBlockers.includes('resident-product-mass-sidecar')) {
    addStage({
      id: 'resident-product-mass-eos-p2g',
      blocker: 'resident-product-mass-sidecar',
      lawNodeId: 'ulg-sph-resident-product-mass-law',
      orderConstraint: 'before-mechanics-p2g',
      reads: ['resident-product-mass', 'sph-particle-state', 'mls-mpm-mechanics'],
      writes: ['mls-mpm-grid-momentum'],
      consumesRetainedBuffers: ['resident-product-mass-buffer'],
      producesRetainedBuffers: ['mls-mpm-grid-buffer'],
      fusionRequirement: 'p2g-must-consume-resident-product-mass-eos-sidecar'
    });
  }

  if (
    normalizedSidecarBlockers.includes('pressure-interface-force-rows')
    || normalizedSidecarBlockers.includes('pressure-interface-force-solver')
  ) {
    addStage({
      id: 'pressure-interface-grid-force-consumption',
      blocker: normalizedSidecarBlockers.includes('pressure-interface-force-solver')
        ? 'pressure-interface-force-solver'
        : 'pressure-interface-force-rows',
      lawNodeId: 'ulg-pressure-interface-force-law',
      orderConstraint: 'before-mechanics-grid-update',
      reads: ['pressure-interface-force-rows', 'mls-mpm-grid-momentum'],
      writes: ['mls-mpm-grid-velocity'],
      consumesRetainedBuffers: ['pressure-interface-force-rows-buffer'],
      producesRetainedBuffers: ['mls-mpm-updated-grid-buffer'],
      stateManagerAdmissionRequired: true,
      fusionRequirement: 'grid-update-must-consume-admitted-pressure-force-rows'
    });
  }

  if (normalizedSidecarBlockers.includes('thermal-sidecar')) {
    addStage({
      id: 'thermal-phase',
      blocker: 'thermal-sidecar',
      implementedInCurrentFusedSequence: thermalSidecarFusionRunnable,
      lawNodeId: 'ulg-sph-thermal-phase-law',
      orderConstraint: 'after-mechanics-g2p-before-reaction',
      reads: ['sph-particle-state', 'sph-thermo-phase', 'thermal-material-table'],
      writes: ['sph-particle-state', 'sph-thermo-phase'],
      consumesRetainedBuffers: ['g2p-state-buffer', 'source-thermo-buffer'],
      producesRetainedBuffers: ['thermal-state-buffer', 'thermal-thermo-buffer'],
      fusionRequirement: 'thermal-runner-must-consume-retained-g2p-state-and-retain-state-thermo'
    });
  }

  if (normalizedSidecarBlockers.includes('reaction-sidecar')) {
    addStage({
      id: 'reaction-product',
      blocker: 'reaction-sidecar',
      lawNodeId: 'ulg-sph-reaction-product-law',
      orderConstraint: normalizedSidecarBlockers.includes('thermal-sidecar')
        ? 'after-thermal-phase-before-mechanics-refresh'
        : 'after-mechanics-g2p-before-mechanics-refresh',
      reads: ['sph-particle-state', 'sph-thermo-phase', 'mls-mpm-mechanics', 'reaction-closure-table'],
      writes: ['sph-particle-state', 'sph-thermo-phase', 'mls-mpm-mechanics', 'resident-product-mass'],
      consumesRetainedBuffers: ['state-buffer', 'thermo-buffer', 'g2p-mechanics-buffer'],
      producesRetainedBuffers: ['reaction-state-buffer', 'reaction-thermo-buffer', 'resident-product-mass-buffer'],
      fusionRequirement: 'reaction-runner-must-retain-particle-and-product-mass-outputs'
    });
  }

  if (
    normalizedSidecarBlockers.includes('thermal-sidecar')
    || normalizedSidecarBlockers.includes('reaction-sidecar')
  ) {
    addStage({
      id: 'mechanics-refresh',
      blocker: normalizedSidecarBlockers.includes('reaction-sidecar') ? 'reaction-sidecar' : 'thermal-sidecar',
      implementedInCurrentFusedSequence: thermalSidecarFusionRunnable,
      lawNodeId: 'ulg-mls-mpm-mechanics-refresh-law',
      orderConstraint: 'after-thermal-or-reaction-before-next-step-p2g',
      reads: ['sph-particle-state', 'sph-thermo-phase', 'mls-mpm-mechanics', 'mechanics-material-table'],
      writes: ['mls-mpm-mechanics'],
      consumesRetainedBuffers: ['state-buffer', 'thermo-buffer', 'g2p-mechanics-buffer'],
      producesRetainedBuffers: ['mechanics-refresh-buffer'],
      conditionalRequired: 'required-when-thermal-or-reaction-changes-phase-without-mechanics-authority',
      fusionRequirement: 'mechanics-refresh-must-run-before-next-fused-step'
    });
  }

  const requiredStageOrder = [
    ...(stages.some((stage) => stage.id === 'resident-product-mass-eos-p2g') ? ['resident-product-mass-eos-p2g'] : []),
    'mechanics-p2g',
    ...(stages.some((stage) => stage.id === 'pressure-interface-grid-force-consumption')
      ? ['pressure-interface-grid-force-consumption']
      : []),
    'mechanics-grid-update',
    'mechanics-g2p',
    ...(stages.some((stage) => stage.id === 'thermal-phase') ? ['thermal-phase'] : []),
    ...(stages.some((stage) => stage.id === 'reaction-product') ? ['reaction-product'] : []),
    ...(stages.some((stage) => stage.id === 'mechanics-refresh') ? ['mechanics-refresh'] : []),
    'resident-compact-summary-or-active-grid-plan'
  ];
  const blockers = sidecarFusionRequired
    ? (thermalSidecarFusionRunnable ? [] : ['sidecar-fusion-execution-not-implemented'])
    : [];
  return {
    schema: ULG_MLS_MPM_FUSED_RESIDENT_SIDECAR_PLAN_SCHEMA,
    status: sidecarFusionRequired
      ? (thermalSidecarFusionRunnable
          ? 'sidecar-fusion-plan-runnable'
          : 'sidecar-fusion-plan-ready-execution-blocked')
      : 'sidecar-fusion-not-required',
    requested: requested === true,
    required: sidecarFusionRequired,
    sequenceRunnableWithSidecars: thermalSidecarFusionRunnable,
    sidecarFusionRunnable: !sidecarFusionRequired || thermalSidecarFusionRunnable,
    thermalSidecarFusionAvailable: thermalSidecarFusionAvailable === true,
    thermalSidecarFusionRunnable,
    stepCount: Math.max(1, Math.round(finiteNumber(stepCount, 1))),
    readbackMode,
    compactSummaryMode: normalizeMlsMpmResidentCompactSummaryMode(compactSummaryMode),
    activeGridRequested: activeGridRequested === true,
    sidecarBlockers: normalizedSidecarBlockers,
    blockers,
    sidecarCount: normalizedSidecarBlockers.length,
    stageCount: stages.length,
    stages,
    requiredStageOrder,
    requiredMechanicsStages: ['mechanics-p2g', 'mechanics-grid-update', 'mechanics-g2p'],
    perStepFallbackMaintainsLawOrdering: sidecarFusionRequired && !thermalSidecarFusionRunnable,
    fallbackModeUntilImplemented: sidecarFusionRequired && !thermalSidecarFusionRunnable
      ? 'per-step-resident-pass-dag-or-per-step-fused-mechanics-active-grid'
      : null,
    ownershipRules: [
      'single-authoritative-owner-after-each-stage',
      'sidecar-writes-must-be-retained-or-admitted-before-next-stage',
      'state-manager-admission-required-before-cross-stage-authoritative-mutation',
      'scene-local-execution-must-not-bypass-law-graph-ordering'
    ],
    promotionStatus: sidecarFusionRequired
      ? (thermalSidecarFusionRunnable
          ? 'contract-ready-execution-promoted'
          : 'contract-ready-execution-not-promoted')
      : 'not-required',
    scientificValidation: false,
    fullPhysicsValidation: false
  };
}

function createFusedResidentSidecarStepEvidence({
  sidecarFusionPlan = null,
  stageStatusSummary = {},
  stageBackendSummary = {},
  thermalStep = null,
  reactionStep = null,
  mechanicsRefreshStep = null,
  p2gGridProjection = null,
  gridUpdate = null,
  thermalOutput = {},
  reactionOutput = {},
  mechanicsRefreshOutput = {}
} = {}) {
  if (!sidecarFusionPlan?.required) return null;
  const sourceStages = Array.isArray(sidecarFusionPlan.stages)
    ? sidecarFusionPlan.stages
    : [];
  const stageEvidence = sourceStages.map((stage, index) => {
    let sourceStatus = null;
    let backend = null;
    let executed = false;
    let retainedOutputSatisfied = false;
    let orderSatisfied = true;
    if (stage.id === 'thermal-phase') {
      sourceStatus = stageStatusSummary.thermal ?? null;
      backend = stageBackendSummary.thermal ?? null;
      executed = Boolean(thermalStep);
      retainedOutputSatisfied = Boolean(thermalOutput.stateBuffer && thermalOutput.thermoBuffer);
      orderSatisfied = Boolean(stageStatusSummary.g2p);
    } else if (stage.id === 'reaction-product') {
      sourceStatus = stageStatusSummary.reaction ?? null;
      backend = stageBackendSummary.reaction ?? null;
      executed = Boolean(reactionStep);
      retainedOutputSatisfied = Boolean(
        reactionOutput.stateBuffer
        && reactionOutput.thermoBuffer
        && (
          reactionOutput.mechanicsBuffer
          || reactionOutput.residentProductMass
          || reactionOutput.residentProductMass?.productEventBufferRetained
        )
      );
      orderSatisfied = Boolean(stageStatusSummary.g2p);
    } else if (stage.id === 'mechanics-refresh') {
      sourceStatus = stageStatusSummary.mechanicsRefresh ?? null;
      backend = stageBackendSummary.mechanicsRefresh ?? null;
      executed = Boolean(mechanicsRefreshStep);
      retainedOutputSatisfied = Boolean(mechanicsRefreshOutput.mechanicsBuffer);
      orderSatisfied = Boolean(stageStatusSummary.thermal || stageStatusSummary.reaction);
    } else if (stage.id === 'pressure-interface-grid-force-consumption') {
      sourceStatus = gridUpdate?.pressureInterfaceForceApplicationStatus ?? null;
      backend = stageBackendSummary.gridUpdate ?? null;
      executed = sourceStatus === 'pressure-interface-grid-force-consumer-applied';
      retainedOutputSatisfied = executed && finiteNumber(gridUpdate?.pressureInterfaceForceRowCount, 0) > 0;
      orderSatisfied = Boolean(stageStatusSummary.p2g);
    } else if (stage.id === 'resident-product-mass-eos-p2g') {
      sourceStatus = p2gGridProjection?.residentProductMassGridCouplingStatus
        ?? p2gGridProjection?.gpuResult?.residentProductMassGridCouplingStatus
        ?? null;
      backend = stageBackendSummary.p2g ?? null;
      executed = sourceStatus === 'resident-product-mass-grid-coupled';
      retainedOutputSatisfied = executed && Boolean(p2gGridProjection?.gpuResult?.gridBuffer || p2gGridProjection?.gridBuffer);
      orderSatisfied = true;
    }
    const passed = executed && retainedOutputSatisfied && orderSatisfied;
    return {
      id: stage.id ?? null,
      blocker: stage.blocker ?? null,
      lawNodeId: stage.lawNodeId ?? null,
      order: index,
      orderConstraint: stage.orderConstraint ?? null,
      sourceStatus,
      backend,
      executed,
      retainedOutputSatisfied,
      orderSatisfied,
      passed,
      status: passed
        ? 'sidecar-fusion-stage-evidence-ready'
        : (executed ? 'sidecar-fusion-stage-output-incomplete' : 'sidecar-fusion-stage-not-executed'),
      fusionRequirement: stage.fusionRequirement ?? null
    };
  });
  const executedStageCount = stageEvidence.filter((stage) => stage.executed).length;
  const passedStageCount = stageEvidence.filter((stage) => stage.passed).length;
  const allRequiredStagesPassed = stageEvidence.length > 0 && passedStageCount === stageEvidence.length;
  const promotesFusedSequence = Boolean(
    allRequiredStagesPassed
    && sidecarFusionPlan.sequenceRunnableWithSidecars === true
  );
  return {
    schema: ULG_MLS_MPM_FUSED_RESIDENT_SIDECAR_STEP_EVIDENCE_SCHEMA,
    status: allRequiredStagesPassed
      ? 'sidecar-fusion-step-evidence-ready'
      : (executedStageCount > 0
          ? 'sidecar-fusion-step-evidence-partial'
          : 'sidecar-fusion-step-evidence-not-executed'),
    sidecarFusionPlanSchema: sidecarFusionPlan.schema ?? null,
    sidecarFusionPlanStatus: sidecarFusionPlan.status ?? null,
    sidecarFusionRequired: sidecarFusionPlan.required === true,
    sidecarFusionRunnable: sidecarFusionPlan.sidecarFusionRunnable === true,
    sidecarBlockers: [...(sidecarFusionPlan.sidecarBlockers || [])],
    requiredStageOrder: [...(sidecarFusionPlan.requiredStageOrder || [])],
    stageCount: stageEvidence.length,
    executedStageCount,
    passedStageCount,
    allRequiredStagesPassed,
    promotesFusedSequence,
    fallbackEvidence: !promotesFusedSequence,
    stages: stageEvidence,
    scientificValidation: false,
    fullPhysicsValidation: false
  };
}

function isResidentSequenceBlockedOnlyBySidecars(blockers = [], sidecarBlockers = []) {
  const normalizedBlockers = uniqueStringList(blockers);
  const normalizedSidecarBlockers = uniqueStringList(sidecarBlockers);
  return normalizedBlockers.length > 0
    && normalizedBlockers.length === normalizedSidecarBlockers.length
    && normalizedBlockers.every((blocker) => normalizedSidecarBlockers.includes(blocker));
}

function thermalSidecarAwareSequenceMode({
  sidecarBlockers = [],
  activeGridEligible = false,
  activeGridEnabled = false
} = {}) {
  const normalizedSidecarBlockers = uniqueStringList(sidecarBlockers);
  if (normalizedSidecarBlockers.length !== 1 || normalizedSidecarBlockers[0] !== 'thermal-sidecar') {
    return null;
  }
  return (activeGridEligible || activeGridEnabled)
    ? 'thermal-mechanics-refresh-per-step-fused-mechanics-active-grid'
    : 'thermal-mechanics-refresh-per-step-pass-dag';
}

function createSidecarAwareResidentSequenceEvidence({
  preflight = null,
  stepSummaries = [],
  completedStepCount = 0
} = {}) {
  const plan = preflight?.sidecarFusionPlan || null;
  if (preflight?.sidecarAwareSequenceCandidate !== true || plan?.required !== true) return null;
  const summaries = Array.isArray(stepSummaries) ? stepSummaries : [];
  const requiredStageCount = Math.max(0, Math.round(finiteNumber(plan.stageCount, 0)));
  const expectedStepCount = Math.max(1, Math.round(finiteNumber(preflight.stepCount, summaries.length || 1)));
  const evidenceByStep = summaries.map((summary, index) => {
    const status = summary.sidecarFusionStepEvidenceStatus ?? null;
    const stageCount = Math.max(0, Math.round(finiteNumber(summary.sidecarFusionStepEvidenceStageCount, 0)));
    const executedStageCount = Math.max(
      0,
      Math.round(finiteNumber(summary.sidecarFusionStepEvidenceExecutedStageCount, 0))
    );
    const passedStageCount = Math.max(
      0,
      Math.round(finiteNumber(summary.sidecarFusionStepEvidencePassedStageCount, 0))
    );
    const allRequiredStagesPassed = Boolean(
      summary.sidecarFusionStepEvidenceAllRequiredStagesPassed
      || (
        status === 'sidecar-fusion-step-evidence-ready'
        && stageCount === requiredStageCount
        && passedStageCount === requiredStageCount
      )
    );
    return {
      index,
      status,
      stageCount,
      executedStageCount,
      passedStageCount,
      allRequiredStagesPassed
    };
  });
  const passedStepCount = evidenceByStep.filter((step) => step.allRequiredStagesPassed).length;
  const partialStepCount = evidenceByStep.filter((step) => (
    !step.allRequiredStagesPassed
    && (
      step.status === 'sidecar-fusion-step-evidence-partial'
      || step.executedStageCount > 0
      || step.passedStageCount > 0
    )
  )).length;
  const missingStepCount = Math.max(0, expectedStepCount - evidenceByStep.length);
  const failedStepCount = Math.max(0, expectedStepCount - passedStepCount - partialStepCount - missingStepCount);
  const allStepsPassed = expectedStepCount > 0
    && Math.max(0, Math.round(finiteNumber(completedStepCount, summaries.length))) === expectedStepCount
    && passedStepCount === expectedStepCount;
  return {
    schema: ULG_MLS_MPM_SIDECAR_AWARE_RESIDENT_SEQUENCE_SCHEMA,
    status: allStepsPassed
      ? 'sidecar-aware-resident-sequence-evidence-ready'
      : (passedStepCount > 0 || partialStepCount > 0
          ? 'sidecar-aware-resident-sequence-evidence-partial'
          : 'sidecar-aware-resident-sequence-evidence-not-ready'),
    mode: preflight.sidecarAwareSequenceMode ?? null,
    runner: preflight.sidecarAwareSequenceRunner ?? null,
    sequencePath: preflight.sidecarAwareSequencePath ?? null,
    directRunnerContract: preflight.sidecarAwareDirectRunnerContract ?? null,
    directRunnerContractStatus: preflight.sidecarAwareDirectRunnerContract?.status ?? null,
    directRunnerEligible: preflight.sidecarAwareDirectRunnerContract?.directRunnerEligible ?? null,
    directRunnerRunnable: preflight.sidecarAwareDirectRunnerContract?.directRunnerRunnable ?? null,
    directRunnerSelected: preflight.sidecarAwareDirectRunnerContract?.directRunnerSelected ?? null,
    directRunnerSelectionStatus: preflight.sidecarAwareDirectRunnerContract?.directRunnerSelectionStatus ?? null,
    sequenceRequested: preflight.sequenceRequested === true,
    sequenceRunnable: false,
    sidecarAwareSequenceCandidate: true,
    sidecarAwareSequenceExecuted: evidenceByStep.length > 0,
    sidecarAwareSequencePromotesFusedSequence: false,
    promotesFusedResidentSequence: false,
    promotesFusedSequence: false,
    fallbackMode: preflight.fallbackMode ?? null,
    activeGridFallbackUsed: preflight.fallbackMode === 'per-step-fused-mechanics-active-grid',
    perStepFusedMechanicsFallbackEligible: preflight.perStepFusedMechanicsFallbackEligible === true,
    sidecarFusionPlanStatus: plan.status ?? null,
    sidecarFusionRequired: plan.required === true,
    sidecarFusionRunnable: plan.sidecarFusionRunnable === true,
    sidecarBlockers: [...(plan.sidecarBlockers || [])],
    requiredStageOrder: [...(plan.requiredStageOrder || [])],
    stageCount: requiredStageCount,
    stepCount: expectedStepCount,
    completedStepCount: Math.max(0, Math.round(finiteNumber(completedStepCount, summaries.length))),
    evidenceStepCount: evidenceByStep.length,
    passedStepCount,
    partialStepCount,
    missingStepCount,
    failedStepCount,
    allStepsPassed,
    stepEvidence: evidenceByStep,
    scientificValidation: false,
    fullPhysicsValidation: false
  };
}

function createThermalSidecarDirectRunnerContract({
  preflight = null,
  thermalMaterialTable = null,
  mechanicsMaterialTable = null,
  thermalStepRunner = null,
  mechanicsRefreshRunner = null,
  reactionTable = null,
  pressureInterfaceForceRowsBuffer = null,
  pressureInterfaceForceSolver = null,
  residentProductMass = null,
  gpuResidentLaneManager = null,
  directRunnerImplementationAvailable = false
} = {}) {
  const sidecarAwareCandidate = preflight?.sidecarAwareSequenceCandidate === true;
  const blockers = [];
  if (!sidecarAwareCandidate) blockers.push('sidecar-aware-sequence-not-candidate');
  if (thermalMaterialTable == null) blockers.push('thermal-material-table-missing');
  if (mechanicsMaterialTable == null) blockers.push('mechanics-material-table-missing');
  if (typeof thermalStepRunner !== 'function') blockers.push('thermal-step-runner-missing');
  if (typeof mechanicsRefreshRunner !== 'function') blockers.push('mechanics-refresh-runner-missing');
  if (reactionTable?.reactionCount > 0) blockers.push('reaction-sidecar-not-supported-by-direct-runner');
  if (pressureInterfaceForceRowsBuffer) blockers.push('pressure-interface-force-rows-not-supported-by-direct-runner');
  if (pressureInterfaceForceSolver) blockers.push('pressure-interface-force-solver-not-supported-by-direct-runner');
  if (residentProductMass) blockers.push('resident-product-mass-not-supported-by-direct-runner');
  if (gpuResidentLaneManager) blockers.push('gpu-resident-lane-manager-not-supported-by-direct-runner');
  if (preflight?.fallbackMode !== 'per-step-fused-mechanics-active-grid') {
    blockers.push('per-step-fused-active-grid-route-required');
  }
  const uniqueBlockers = uniqueStringList(blockers);
  const eligible = sidecarAwareCandidate && uniqueBlockers.length === 0;
  const runnable = eligible && directRunnerImplementationAvailable === true;
  const selected = runnable;
  return {
    schema: ULG_MLS_MPM_THERMAL_SIDECAR_DIRECT_RUNNER_CONTRACT_SCHEMA,
    status: runnable
      ? 'thermal-sidecar-direct-runner-selected'
      : (eligible
      ? 'thermal-sidecar-direct-runner-contract-ready-execution-pending'
      : (sidecarAwareCandidate
          ? 'thermal-sidecar-direct-runner-contract-blocked'
          : 'thermal-sidecar-direct-runner-not-candidate')),
    mode: preflight?.sidecarAwareSequenceMode ?? null,
    requiredRoute: 'thermal-mechanics-refresh-per-step-fused-mechanics-active-grid',
    sidecarAwareSequenceCandidate: sidecarAwareCandidate,
    directRunnerEligible: eligible,
    directRunnerImplementationAvailable: directRunnerImplementationAvailable === true,
    directRunnerRunnable: runnable,
    directRunnerSelected: selected,
    directRunnerSelectionStatus: selected
      ? 'direct-runner-selected'
      : (eligible
          ? 'direct-runner-implementation-pending'
          : 'direct-runner-requirements-not-met'),
    directRunnerSelectionBlockers: selected
      ? []
      : (eligible
          ? ['direct-runner-implementation-pending']
          : uniqueBlockers),
    blockers: uniqueBlockers,
    sidecarBlockers: [...(preflight?.sidecarBlockers || [])],
    sidecarFusionPlanStatus: preflight?.sidecarFusionPlanStatus ?? null,
    requiredStageOrder: [...(preflight?.sidecarFusionPlan?.requiredStageOrder || [])],
    requiredRunnerStages: [
      'fused-mechanics-step',
      'thermal-phase',
      'mechanics-refresh',
      'resident-compact-summary-or-active-grid-plan'
    ],
    requiredRetainedBuffers: [
      'g2p-state-buffer',
      'g2p-mechanics-buffer',
      'thermal-state-buffer',
      'thermal-thermo-buffer',
      'mechanics-refresh-buffer'
    ],
    unsupportedSidecars: [
      'reaction-sidecar',
      'pressure-interface-force-sidecar',
      'resident-product-mass-sidecar'
    ],
    currentRoute: preflight?.sidecarAwareSequencePath ?? null,
    currentRunner: preflight?.sidecarAwareSequenceRunner ?? null,
    fallbackMode: preflight?.fallbackMode ?? null,
    genericRouteActiveUntilDirectRunnerSelected: true,
    scientificValidation: false,
    fullPhysicsValidation: false
  };
}

function createFusedResidentSequencePreflight({
  requested = false,
  stepCount = 1,
  readbackMode = FULL_READBACK_MODE,
  compactSummaryMode = MLS_MPM_RESIDENT_COMPACT_SUMMARY_MODE_EVERY_STEP,
  preferWebGpu = false,
  device = null,
  sphParticleUpload = null,
  mlsMpmParticleUpload = null,
  requestPerStepFusedNoFullMechanics = false,
  requestActiveGridFusedNoFullMechanics = false,
  customRunnerBlockers = [],
  sidecarBlockers = [],
  thermalSidecarFusionAvailable = false
} = {}) {
  const normalizedStepCount = Math.max(1, Math.round(finiteNumber(stepCount, 1)));
  const normalizedCompactSummaryMode = normalizeMlsMpmResidentCompactSummaryMode(compactSummaryMode);
  const sequenceRequested = requested === true;
  const normalizedSidecarBlockers = uniqueStringList(sidecarBlockers);
  const sidecarFusionPlan = createFusedResidentSidecarFusionPlan({
    requested: sequenceRequested,
    stepCount: normalizedStepCount,
    readbackMode,
    compactSummaryMode: normalizedCompactSummaryMode,
    activeGridRequested: requestActiveGridFusedNoFullMechanics,
    sidecarBlockers: normalizedSidecarBlockers,
    thermalSidecarFusionAvailable
  });
  const blockers = [];
  if (sequenceRequested) {
    if (normalizedStepCount <= 1) blockers.push('step-count-not-greater-than-one');
    if (normalizedCompactSummaryMode === MLS_MPM_RESIDENT_COMPACT_SUMMARY_MODE_EVERY_STEP) {
      blockers.push('compact-summary-every-step');
    }
    if (readbackMode !== NO_FULL_READBACK_MODE) blockers.push('full-readback-requested');
    if (preferWebGpu !== true) blockers.push('webgpu-not-preferred');
    if (!(device?.createBuffer && device.queue?.writeBuffer)) blockers.push('webgpu-device-unavailable');
    if (sphParticleUpload?.status !== 'webgpu-uploaded') blockers.push('sph-particle-upload-not-resident');
    if (mlsMpmParticleUpload?.status !== 'webgpu-uploaded') blockers.push('mls-mpm-upload-not-resident');
    blockers.push(...uniqueStringList(customRunnerBlockers));
    if (sidecarFusionPlan.sequenceRunnableWithSidecars !== true) {
      blockers.push(...normalizedSidecarBlockers);
    }
  }
  const uniqueBlockers = uniqueStringList(blockers);
  const sequenceRunnable = sequenceRequested && uniqueBlockers.length === 0;
  const perStepFusedMechanicsFallbackEligible = Boolean(
    sequenceRequested
    && requestPerStepFusedNoFullMechanics
    && requestActiveGridFusedNoFullMechanics
    && readbackMode === NO_FULL_READBACK_MODE
    && preferWebGpu === true
    && device?.createBuffer
    && device.queue?.writeBuffer
    && sphParticleUpload?.status === 'webgpu-uploaded'
    && mlsMpmParticleUpload?.status === 'webgpu-uploaded'
  );
  const fallbackMode = sequenceRunnable
    ? 'fused-no-full-resident-mechanics-sequence'
    : (perStepFusedMechanicsFallbackEligible
        ? 'per-step-fused-mechanics-active-grid'
        : 'per-step-resident-pass-dag');
  const sidecarOnlySequenceBlocked = sequenceRequested
    && !sequenceRunnable
    && isResidentSequenceBlockedOnlyBySidecars(uniqueBlockers, normalizedSidecarBlockers);
  const sidecarAwareSequenceMode = sidecarOnlySequenceBlocked
    ? thermalSidecarAwareSequenceMode({
        sidecarBlockers: normalizedSidecarBlockers,
        activeGridEligible: perStepFusedMechanicsFallbackEligible
      })
    : null;
  const sidecarAwareSequenceCandidate = Boolean(sidecarAwareSequenceMode);
  return {
    schema: ULG_MLS_MPM_FUSED_RESIDENT_SEQUENCE_PREFLIGHT_SCHEMA,
    status: sequenceRunnable
      ? 'fused-resident-sequence-preflight-ready'
      : (sequenceRequested ? 'blocked-fused-resident-sequence' : 'fused-resident-sequence-not-requested'),
    sequenceRequested,
    sequenceRunnable,
    stepCount: normalizedStepCount,
    readbackMode,
    compactSummaryMode: normalizedCompactSummaryMode,
    preferWebGpu: preferWebGpu === true,
    deviceReady: Boolean(device?.createBuffer && device.queue?.writeBuffer),
    residentUploadsReady: Boolean(
      sphParticleUpload?.status === 'webgpu-uploaded'
      && mlsMpmParticleUpload?.status === 'webgpu-uploaded'
    ),
    blockers: uniqueBlockers,
    sidecarBlockers: normalizedSidecarBlockers,
    customRunnerBlockers: uniqueStringList(customRunnerBlockers),
    sidecarFusionRequired: sidecarFusionPlan.required,
    sidecarFusionRunnable: sidecarFusionPlan.sidecarFusionRunnable,
    sidecarFusionPlanStatus: sidecarFusionPlan.status,
    sidecarFusionStageCount: sidecarFusionPlan.stageCount,
    sidecarFusionPlan,
    sidecarFusionPromotesFusedSequence: sidecarFusionPlan.sequenceRunnableWithSidecars === true,
    sequenceRunnableWithSidecars: sidecarFusionPlan.sequenceRunnableWithSidecars === true,
    fallbackMode,
    perStepFusedMechanicsFallbackEligible,
    sidecarOnlySequenceBlocked,
    sidecarAwareSequenceCandidate,
    sidecarAwareSequenceStatus: sidecarAwareSequenceCandidate
      ? 'sidecar-aware-sequence-candidate-awaiting-step-evidence'
      : null,
    sidecarAwareSequenceMode,
    sidecarAwareSequenceRunner: sidecarAwareSequenceCandidate
      ? 'resident-sidecar-aware-sequence-loop'
      : null,
    sidecarAwareSequencePath: sidecarAwareSequenceCandidate
      ? 'explicit-sidecar-aware-per-step-resident-loop'
      : null,
    sidecarAwareSequencePromotesFusedSequence: false,
    sidecarAwareSequenceSupportedBlockers: ['thermal-sidecar'],
    activeGridFallbackRequested: requestActiveGridFusedNoFullMechanics === true,
    thermalAwareFusionRequired: normalizedSidecarBlockers.includes('thermal-sidecar'),
    reactionAwareFusionRequired: normalizedSidecarBlockers.includes('reaction-sidecar'),
    pressureInterfaceAwareFusionRequired:
      normalizedSidecarBlockers.includes('pressure-interface-force-rows')
      || normalizedSidecarBlockers.includes('pressure-interface-force-solver'),
    residentProductMassAwareFusionRequired: normalizedSidecarBlockers.includes('resident-product-mass-sidecar')
  };
}

function createResidentSequenceLaneContract({
  laneId,
  stateKey,
  domainKey = null,
  stepCount = 1,
  readbackMode = FULL_READBACK_MODE,
  compactSummaryMode = MLS_MPM_RESIDENT_COMPACT_SUMMARY_MODE_EVERY_STEP,
  queueFencePolicy,
  readFamilies = [],
  writeFamilies = [],
  retainedBufferRefs = [],
  activeGridDispatchPolicy = null,
  fusedResidentSequence = false,
  sidecarBlockers = [],
  thermalSidecarFusionAvailable = false
} = {}) {
  const normalizedStepCount = Math.max(1, Math.round(finiteNumber(stepCount, 1)));
  const normalizedCompactSummaryMode = normalizeMlsMpmResidentCompactSummaryMode(compactSummaryMode);
  const sequenceRequested = fusedResidentSequence === true;
  const normalizedSidecarBlockers = uniqueStringList(sidecarBlockers);
  const sidecarFusionPlan = createFusedResidentSidecarFusionPlan({
    requested: sequenceRequested,
    stepCount: normalizedStepCount,
    readbackMode,
    compactSummaryMode: normalizedCompactSummaryMode,
    activeGridRequested: activeGridDispatchPolicy?.enabled === true,
    sidecarBlockers: normalizedSidecarBlockers,
    thermalSidecarFusionAvailable
  });
  const requirementBlockers = [];
  if (sequenceRequested) {
    if (normalizedStepCount <= 1) requirementBlockers.push('step-count-not-greater-than-one');
    if (readbackMode !== NO_FULL_READBACK_MODE) requirementBlockers.push('full-readback-requested');
    if (normalizedCompactSummaryMode === MLS_MPM_RESIDENT_COMPACT_SUMMARY_MODE_EVERY_STEP) {
      requirementBlockers.push('compact-summary-every-step');
    }
    if (sidecarFusionPlan.sequenceRunnableWithSidecars !== true) {
      requirementBlockers.push(...normalizedSidecarBlockers);
    }
  }
  const blockers = uniqueStringList(requirementBlockers);
  const sequenceRunnable = sequenceRequested
    && normalizedStepCount > 1
    && readbackMode === NO_FULL_READBACK_MODE
    && normalizedCompactSummaryMode !== MLS_MPM_RESIDENT_COMPACT_SUMMARY_MODE_EVERY_STEP
    && blockers.length === 0;
  const activeGridEnabled = activeGridDispatchPolicy?.enabled === true;
  const sequenceMode = sequenceRunnable
    ? (activeGridEnabled
      ? 'fused-no-full-active-grid-mechanics-sequence'
      : 'fused-no-full-full-grid-mechanics-sequence')
    : 'per-step-resident-pass-dag';
  const fallbackMode = sequenceRunnable
    ? sequenceMode
    : (sequenceRequested && activeGridEnabled
        ? 'per-step-fused-mechanics-active-grid'
        : 'per-step-resident-pass-dag');
  const sidecarOnlySequenceBlocked = sequenceRequested
    && !sequenceRunnable
    && isResidentSequenceBlockedOnlyBySidecars(blockers, normalizedSidecarBlockers);
  const sidecarAwareSequenceMode = sidecarOnlySequenceBlocked
    ? thermalSidecarAwareSequenceMode({
        sidecarBlockers: normalizedSidecarBlockers,
        activeGridEnabled
      })
    : null;
  const sidecarAwareSequenceCandidate = Boolean(sidecarAwareSequenceMode);
  return {
    schema: ULG_MLS_MPM_RESIDENT_SEQUENCE_LANE_CONTRACT_SCHEMA,
    authority: 'compute-manager-gpuhub-resident-lane-contract',
    status: sequenceRunnable
      ? 'lane-owned-fused-sequence-contract-ready'
      : (sequenceRequested ? 'blocked-fused-sequence-requirements-not-met' : 'per-step-pass-dag-contract'),
    laneId,
    stateKey,
    domainKey,
    queueFencePolicy,
    stepCount: normalizedStepCount,
    readbackMode,
    compactSummaryMode: normalizedCompactSummaryMode,
    sequenceRequested,
    sequenceRunnable,
    blockers,
    sidecarBlockers: normalizedSidecarBlockers,
    sidecarFusionRequired: sidecarFusionPlan.required,
    sidecarFusionRunnable: sidecarFusionPlan.sidecarFusionRunnable,
    sidecarFusionPlanStatus: sidecarFusionPlan.status,
    sidecarFusionStageCount: sidecarFusionPlan.stageCount,
    sidecarFusionPlan,
    sidecarFusionPromotesFusedSequence: sidecarFusionPlan.sequenceRunnableWithSidecars === true,
    sequenceRunnableWithSidecars: sidecarFusionPlan.sequenceRunnableWithSidecars === true,
    sequenceMode,
    fallbackMode,
    sidecarOnlySequenceBlocked,
    sidecarAwareSequenceCandidate,
    sidecarAwareSequenceStatus: sidecarAwareSequenceCandidate
      ? 'sidecar-aware-sequence-candidate-awaiting-step-evidence'
      : null,
    sidecarAwareSequenceMode,
    sidecarAwareSequenceRunner: sidecarAwareSequenceCandidate
      ? 'resident-sidecar-aware-sequence-loop'
      : null,
    sidecarAwareSequencePath: sidecarAwareSequenceCandidate
      ? 'explicit-sidecar-aware-per-step-resident-loop'
      : null,
    sidecarAwareSequencePromotesFusedSequence: false,
    sidecarAwareSequenceSupportedBlockers: ['thermal-sidecar'],
    thermalAwareFusionRequired: normalizedSidecarBlockers.includes('thermal-sidecar'),
    reactionAwareFusionRequired: normalizedSidecarBlockers.includes('reaction-sidecar'),
    pressureInterfaceAwareFusionRequired:
      normalizedSidecarBlockers.includes('pressure-interface-force-rows')
      || normalizedSidecarBlockers.includes('pressure-interface-force-solver'),
    residentProductMassAwareFusionRequired: normalizedSidecarBlockers.includes('resident-product-mass-sidecar'),
    activeGridDispatchPolicy,
    defaultEnabled: false,
    laneMustRetainBuffers: [...retainedBufferRefs],
    readFamilies: [...readFamilies],
    writeFamilies: [...writeFamilies],
    passDagStages: [
      {
        id: 'mechanics-p2g',
        lawNodeId: 'ulg-mls-mpm-mechanics-law',
        runtimeTarget: 'webgpu-compute',
        reads: ['sph-particle-state', 'mls-mpm-mechanics'],
        writes: ['mls-mpm-grid-momentum']
      },
      {
        id: 'mechanics-grid-update',
        lawNodeId: 'ulg-mls-mpm-mechanics-law',
        runtimeTarget: 'webgpu-compute',
        reads: ['mls-mpm-grid-momentum', 'pressure-interface-force-rows'],
        writes: ['mls-mpm-grid-velocity']
      },
      {
        id: 'mechanics-g2p',
        lawNodeId: 'ulg-mls-mpm-mechanics-law',
        runtimeTarget: 'webgpu-compute',
        reads: ['mls-mpm-grid-velocity', 'sph-particle-state', 'mls-mpm-mechanics'],
        writes: ['sph-particle-state', 'mls-mpm-mechanics']
      },
      {
        id: 'resident-compact-summary',
        lawNodeId: 'ulg-mls-mpm-sph-resident-pass-dag',
        runtimeTarget: 'webgpu-compute',
        reads: ['sph-particle-state', 'sph-thermo-phase', 'mls-mpm-mechanics'],
        writes: ['resident-compact-summary']
      }
    ],
    ownershipRules: [
      'single-authoritative-owner-after-each-stage',
      'same-device-hot-buffers-retained-until-fence-or-explicit-handoff',
      'state-manager-admission-required-before-authoritative-mutation',
      'scene-local-execution-must-not-become-a-parallel-scheduler'
    ],
    promotionStatus: activeGridEnabled
      ? 'active-grid-opt-in-scene-evidence-ready'
      : (sequenceRunnable ? 'fused-sequence-opt-in-evidence-ready' : 'metadata-only')
  };
}

function createResidentGpuLaneTaskDescriptor({
  laneId,
  stateKey,
  domainKey = null,
  solverId,
  owner,
  localExecution = 'inline',
  readFamilies = [],
  writeFamilies = [],
  retainedBufferRefs = [],
  queueFencePolicy,
  copyBudget,
  activeGridDispatchPolicy = null,
  residentSequenceLaneContract = null
}) {
  return {
    schema: PEERCOMPUTE_GPU_RESIDENT_LANE_TASK_SCHEMA,
    enabled: true,
    localExecution: localExecution === 'worker' ? 'worker' : 'inline',
    laneId,
    stateKey,
    domainKey,
    solverId,
    owner,
    readFamilies: [...readFamilies],
    writeFamilies: [...writeFamilies],
    retainedBufferRefs: [...retainedBufferRefs],
    queueFencePolicy,
    copyBudget: { ...copyBudget },
    activeGridDispatchPolicy,
    residentSequenceLaneContract
  };
}

export function createMlsMpmResidentStepComputeTask({
  modulePath,
  taskId = null,
  taskFamily = 'ulg-mls-mpm-sph-resident-step',
  solverId = 'ulg-mls-mpm-sph-resident-step',
  owner = 'ulg-sph-resident-step',
  lawGraphId = 'peercompute.ulg.local-sph-law-closure-graph',
  lawGraphNodeId = 'ulg-mls-mpm-sph-resident-step',
  laneId = 'ulg:sph-resident:active',
  stateKey = 'ulg:sph-resident-state',
  domainKey = null,
  localExecution = 'inline',
  queueFencePolicy = 'queue.onSubmittedWorkDone-before-admission',
  readFamilies = ['sph-particle-state', 'mls-mpm-mechanics', 'resident-product-mass', 'pressure-interface-force-rows'],
  writeFamilies = ['sph-particle-state', 'sph-thermo-phase', 'mls-mpm-mechanics', 'resident-product-mass'],
  retainedBufferRefs = ['sph-state-buffer', 'sph-thermo-buffer', 'mls-mpm-mechanics-buffer'],
  returnEnvelope = true,
  suppressCommitDelta = false,
  ...residentStepOptions
} = {}) {
  if (typeof modulePath !== 'string' || modulePath.trim() === '') {
    throw new Error('createMlsMpmResidentStepComputeTask requires a modulePath for the ULG resident step task handler');
  }
  const {
    gpuResidentLaneManager: _ignoredLaneManager,
    gpuResidentLaneId: _ignoredLaneId,
    gpuResidentLaneStateKey: _ignoredLaneStateKey,
    gpuResidentLaneDomainKey: _ignoredLaneDomainKey,
    ...taskStepOptions
  } = residentStepOptions;
  const readbackMode = taskStepOptions.readbackMode === NO_FULL_READBACK_MODE ? NO_FULL_READBACK_MODE : FULL_READBACK_MODE;
  const hotLoopBudget = summarizeMlsMpmResidentHotLoopBudget({
    ...taskStepOptions,
    readbackMode,
    gpuResidentLaneCopyBudget: residentStepOptions.gpuResidentLaneCopyBudget
  });
  const laneCopyBudget = hotLoopBudget.copyBudget;
  const lawGraphNode = createResidentLawGraphNodeTaskRef({
    graphId: lawGraphId,
    nodeId: lawGraphNodeId,
    solverId,
    readFamilies,
    writeFamilies
  });
  lawGraphNode.hotLoopBudget = hotLoopBudget;
  const gpuFence = createResidentGpuFenceRequirement({
    laneId,
    stateKey,
    queueFencePolicy,
    retainedBufferRefs,
    source: 'ulg-mls-mpm-resident-step-compute-task'
  });
  const gpuResidentLane = createResidentGpuLaneTaskDescriptor({
    laneId,
    stateKey,
    domainKey,
    solverId,
    owner,
    localExecution,
    readFamilies,
    writeFamilies,
    retainedBufferRefs,
    queueFencePolicy,
    copyBudget: laneCopyBudget
  });
  gpuResidentLane.hotLoopBudget = hotLoopBudget;
  const id = taskId || `ulg-mls-mpm-resident-step:${finiteNumber(taskStepOptions.sphParticleState?.step ?? taskStepOptions.mlsMpmParticleState?.step, 0)}`;
  return {
    schema: ULG_MLS_MPM_RESIDENT_COMPUTE_TASK_SCHEMA,
    id,
    runtime: 'js',
    taskFamily,
    solverId,
    module: modulePath,
    exportName: 'runMlsMpmResidentStepComputeTask',
    returnEnvelope,
    suppressCommitDelta,
    residency: 'gpu-lane',
    lawGraphNode,
    readFamilies: [...readFamilies],
    writeFamilies: [...writeFamilies],
    expectedOutputFamilies: [...writeFamilies],
    webgpu: {
      residency: 'gpu-lane',
      requiresQueueFence: true,
      laneId,
      stateKey,
      domainKey,
      queueFencePolicy,
      retainedBufferRefs: [...retainedBufferRefs],
      copyBudget: { ...laneCopyBudget },
      hotLoopBudget
    },
    gpuFence,
    gpuResidentLane,
    data: {
      ...taskStepOptions,
      readbackMode,
      gpuFenceRequirement: gpuFence,
      gpuResidentLane,
      lawGraphNode,
      hotLoopBudget,
      computeTaskSchema: ULG_MLS_MPM_RESIDENT_COMPUTE_TASK_SCHEMA
    }
  };
}

export async function runMlsMpmResidentStepComputeTask(data = {}) {
  const {
    gpuResidentLaneManager: _ignoredLaneManager,
    gpuFenceRequirement = null,
    gpuResidentLane = null,
    lawGraphNode = null,
    computeTaskSchema = ULG_MLS_MPM_RESIDENT_COMPUTE_TASK_SCHEMA,
    ...residentStepOptions
  } = data || {};
  const resolvedFenceRequirement = gpuFenceRequirement || gpuResidentLane || {};
  const fenceDevice = residentStepOptions.device || residentStepOptions.deviceResult?.device || null;
  const step = await runMlsMpmResidentStepWithOptionalWebGpu({
    ...residentStepOptions,
    gpuResidentLaneManager: null
  });
  await awaitResidentComputeTaskQueueFence(
    step,
    resolvedFenceRequirement,
    fenceDevice
  );
  const gpuFence = createMlsMpmResidentStepGpuFenceReport(
    step,
    resolvedFenceRequirement
  );
  const schroederAdoptedParticleStorageDescriptor =
    createSchroederAdoptedParticleStorageDescriptorFromStep(step, {
      gpuFence,
      stateKey: gpuFence?.stateKey || gpuResidentLane?.stateKey || null,
      source: 'ulg-mls-mpm-resident-step-compute-task',
      taskId: null
    });
  return {
    ...step,
    schema: step?.schema || ULG_MLS_MPM_GPU_RESIDENT_STEP_SCHEMA,
    computeTaskResultSchema: ULG_MLS_MPM_RESIDENT_COMPUTE_TASK_RESULT_SCHEMA,
    computeTaskSchema,
    lawGraphNode,
    gpuFence,
    gpuFenceReport: gpuFence,
    gpuResidentLaneRequirement: gpuResidentLane || null,
    schroederAdoptedParticleStorageDescriptor,
    schroederParticleStorageContinuationAvailable:
      schroederAdoptedParticleStorageDescriptor?.ready === true,
    schroederParticleStorageRawGpuBufferTransferDetected:
      schroederAdoptedParticleStorageDescriptor?.rawGpuBufferTransferDetected === true
  };
}

export function submitMlsMpmResidentStepComputeTask({ computeManager, ...taskOptions } = {}) {
  if (!computeManager || typeof computeManager.submitTask !== 'function') {
    throw new Error('submitMlsMpmResidentStepComputeTask requires a ComputeManager-compatible submitTask() method');
  }
  return computeManager.submitTask(createMlsMpmResidentStepComputeTask(taskOptions));
}

export function createMlsMpmResidentStepsComputeTask({
  modulePath,
  taskId = null,
  taskFamily = 'ulg-mls-mpm-sph-resident-steps',
  solverId = 'ulg-mls-mpm-sph-resident-steps',
  owner = 'ulg-sph-resident-steps',
  lawGraphId = 'peercompute.ulg.local-sph-law-closure-graph',
  lawGraphNodeId = 'ulg-mls-mpm-sph-resident-pass-dag',
  laneId = 'ulg:sph-resident:active',
  stateKey = 'ulg:sph-resident-state',
  domainKey = null,
  localExecution = 'inline',
  queueFencePolicy = 'queue.onSubmittedWorkDone-before-admission',
  readFamilies = ['sph-particle-state', 'mls-mpm-mechanics', 'resident-product-mass', 'pressure-interface-force-rows'],
  writeFamilies = ['sph-particle-state', 'sph-thermo-phase', 'mls-mpm-mechanics', 'resident-product-mass'],
  retainedBufferRefs = ['sph-state-buffer', 'sph-thermo-buffer', 'mls-mpm-mechanics-buffer'],
  returnEnvelope = true,
  suppressCommitDelta = false,
  emitCommitDelta = true,
  commitDeltaScope = 'ulg-sph-resident-pass-dag',
  commitDeltaStateKey = null,
  ...residentStepOptions
} = {}) {
  if (typeof modulePath !== 'string' || modulePath.trim() === '') {
    throw new Error('createMlsMpmResidentStepsComputeTask requires a modulePath for the ULG resident steps task handler');
  }
  const {
    gpuResidentLaneManager: _ignoredLaneManager,
    gpuResidentLaneId: _ignoredLaneId,
    gpuResidentLaneStateKey: _ignoredLaneStateKey,
    gpuResidentLaneDomainKey: _ignoredLaneDomainKey,
    ...taskStepOptions
  } = residentStepOptions;
  const readbackMode = taskStepOptions.readbackMode === NO_FULL_READBACK_MODE ? NO_FULL_READBACK_MODE : FULL_READBACK_MODE;
  const stepCount = Math.max(1, Math.round(finiteNumber(taskStepOptions.stepCount, 1)));
  const compactSummaryMode = normalizeMlsMpmResidentCompactSummaryMode(taskStepOptions.compactSummaryMode);
  const activeGridDispatchPlanRefreshMode = normalizeMlsMpmActiveGridPlanRefreshMode(
    taskStepOptions.activeGridDispatchPlanRefreshMode
  );
  const activeGridDispatchPolicy = createResidentActiveGridDispatchPolicy({
    requested: Boolean(taskStepOptions.fuseNoFullResidentMechanicsActiveGrid || taskStepOptions.fuseNoFullResidentActiveGrid),
    fusedResidentSequence: Boolean(taskStepOptions.fuseNoFullResidentMechanicsSequence),
    stepCount,
    readbackMode,
    compactSummaryMode,
    activeGridDispatchPlanRefreshMode,
    safetyCells: taskStepOptions.activeGridSafetyCells ?? taskStepOptions.fusedActiveGridSafetyCells
  });
  const residentSequenceSidecarBlockers = fusedResidentSequenceSidecarBlockers({
    thermalMaterialTable: taskStepOptions.thermalMaterialTable,
    reactionTable: taskStepOptions.reactionTable,
    pressureInterfaceForceRowsBuffer: taskStepOptions.pressureInterfaceForceRowsBuffer,
    pressureInterfaceForceSolver: taskStepOptions.pressureInterfaceForceSolver,
    residentProductMass: taskStepOptions.residentProductMass ?? taskStepOptions.nextParticleUploads?.residentProductMass ?? null,
    phaseCarrierPlan: taskStepOptions.sphParticleUpload?.phaseCarrierPlan
      || taskStepOptions.sphParticleState?.phaseCarrierPlan
      || null
  });
  const thermalSidecarFusionAvailable = Boolean(
    taskStepOptions.fuseThermalSidecarResidentSequence === true
    && taskStepOptions.thermalMaterialTable
    && taskStepOptions.mechanicsMaterialTable
    && (taskStepOptions.thermalStepRunner == null || taskStepOptions.thermalStepRunner === runSphThermalStepWebGpu)
    && (
      taskStepOptions.mechanicsRefreshRunner == null
      || taskStepOptions.mechanicsRefreshRunner === runMlsMpmMechanicsRefreshWithOptionalWebGpu
    )
  );
  const residentSequenceLaneContract = createResidentSequenceLaneContract({
    laneId,
    stateKey,
    domainKey,
    stepCount,
    readbackMode,
    compactSummaryMode,
    queueFencePolicy,
    readFamilies,
    writeFamilies,
    retainedBufferRefs,
    activeGridDispatchPolicy,
    fusedResidentSequence: Boolean(taskStepOptions.fuseNoFullResidentMechanicsSequence),
    sidecarBlockers: residentSequenceSidecarBlockers,
    thermalSidecarFusionAvailable
  });
  const hotLoopBudget = summarizeMlsMpmResidentHotLoopBudget({
    ...taskStepOptions,
    readbackMode,
    stepCount,
    compactSummaryMode,
    activeGridDispatchPolicy,
    gpuResidentLaneCopyBudget: residentStepOptions.gpuResidentLaneCopyBudget
  });
  const laneCopyBudget = hotLoopBudget.copyBudget;
  const lawGraphNode = createResidentLawGraphNodeTaskRef({
    graphId: lawGraphId,
    nodeId: lawGraphNodeId,
    solverId,
    readFamilies,
    writeFamilies
  });
  lawGraphNode.activeGridDispatchPolicy = activeGridDispatchPolicy;
  lawGraphNode.residentSequenceLaneContract = residentSequenceLaneContract;
  lawGraphNode.hotLoopBudget = hotLoopBudget;
  const gpuFence = createResidentGpuFenceRequirement({
    laneId,
    stateKey,
    queueFencePolicy,
    retainedBufferRefs,
    source: 'ulg-mls-mpm-resident-steps-compute-task'
  });
  const gpuResidentLane = createResidentGpuLaneTaskDescriptor({
    laneId,
    stateKey,
    domainKey,
    solverId,
    owner,
    localExecution,
    readFamilies,
    writeFamilies,
    retainedBufferRefs,
    queueFencePolicy,
    copyBudget: laneCopyBudget,
    activeGridDispatchPolicy,
    residentSequenceLaneContract
  });
  gpuResidentLane.hotLoopBudget = hotLoopBudget;
  const id = taskId || `ulg-mls-mpm-resident-steps:${finiteNumber(taskStepOptions.sphParticleState?.step ?? taskStepOptions.mlsMpmParticleState?.step, 0)}:${stepCount}`;
  return {
    schema: ULG_MLS_MPM_RESIDENT_STEPS_COMPUTE_TASK_SCHEMA,
    id,
    runtime: 'js',
    taskFamily,
    solverId,
    module: modulePath,
    exportName: 'runMlsMpmResidentStepsComputeTask',
    returnEnvelope,
    suppressCommitDelta,
    residency: 'gpu-lane',
    lawGraphNode,
    readFamilies: [...readFamilies],
    writeFamilies: [...writeFamilies],
    expectedOutputFamilies: [...writeFamilies],
    webgpu: {
      residency: 'gpu-lane',
      requiresQueueFence: true,
      laneId,
      stateKey,
      domainKey,
      queueFencePolicy,
      retainedBufferRefs: [...retainedBufferRefs],
      copyBudget: { ...laneCopyBudget },
      hotLoopBudget,
      activeGridDispatchPolicy,
      residentSequenceLaneContract
    },
    gpuFence,
    gpuResidentLane,
    data: {
      ...taskStepOptions,
      stepCount,
      readbackMode,
      compactSummaryMode,
      activeGridDispatchPlanRefreshMode,
      activeGridDispatchPolicy,
      residentSequenceLaneContract,
      hotLoopBudget,
      gpuFenceRequirement: gpuFence,
      gpuResidentLane,
      lawGraphNode,
      computeTaskSchema: ULG_MLS_MPM_RESIDENT_STEPS_COMPUTE_TASK_SCHEMA,
      computeTaskId: id,
      emitCommitDelta,
      commitDeltaScope,
      commitDeltaStateKey: commitDeltaStateKey || stateKey,
      expectedOutputFamilies: [...writeFamilies]
    }
  };
}

function createMlsMpmResidentStepsSolverTaskBridgeMetadata(baseTask, solverTask = null, {
  status = null,
  reason = null
} = {}) {
  const solverData = solverTask?.data && typeof solverTask.data === 'object' ? solverTask.data : {};
  return {
    schema: ULG_MLS_MPM_RESIDENT_STEPS_SOLVER_TASK_BRIDGE_SCHEMA,
    status: status || (solverTask ? 'solver-task-created' : 'direct-ulg-task'),
    created: Boolean(solverTask),
    reason: reason || null,
    solverTaskSchema: solverData.schema || null,
    solverId: solverTask?.solverId || baseTask?.solverId || null,
    taskFamily: solverTask?.taskFamily || baseTask?.taskFamily || null,
    runtime: solverTask?.runtime || baseTask?.runtime || null,
    module: solverTask?.module || baseTask?.module || null,
    exportName: solverTask?.exportName || baseTask?.exportName || null,
    affinityKey: solverTask?.affinityKey || null,
    warmDeltaScope: solverData.scope || solverData.solver?.warmDelta?.scope || null,
    placementHint: solverTask?.placementHint || null
  };
}

export function createMlsMpmResidentStepsSolverComputeTask({
  computeManager = null,
  ...taskOptions
} = {}) {
  const baseTask = createMlsMpmResidentStepsComputeTask(taskOptions);
  const solverRegistry = computeManager?.solverRegistry;
  if (!solverRegistry || typeof solverRegistry.createTask !== 'function') {
    const bridge = createMlsMpmResidentStepsSolverTaskBridgeMetadata(baseTask, null, {
      status: 'direct-ulg-task',
      reason: 'solver-registry-unavailable'
    });
    return {
      ...baseTask,
      peerComputeSolverTask: bridge,
      data: {
        ...baseTask.data,
        peerComputeSolverTask: bridge
      }
    };
  }

  let solverTask = null;
  try {
    const stateKey = baseTask.gpuResidentLane?.stateKey
      || baseTask.data?.commitDeltaStateKey
      || baseTask.webgpu?.stateKey
      || baseTask.id;
    solverTask = solverRegistry.createTask(baseTask.solverId, {
      id: baseTask.id,
      stateKey,
      scope: baseTask.data?.commitDeltaScope || 'ulg-sph-resident-pass-dag',
      input: {
        stateKey,
        laneId: baseTask.gpuResidentLane?.laneId || baseTask.webgpu?.laneId || null,
        domainKey: baseTask.gpuResidentLane?.domainKey || baseTask.webgpu?.domainKey || null,
        stepCount: baseTask.data?.stepCount ?? null,
        readbackMode: baseTask.data?.readbackMode || null,
        activeGridDispatchPolicy: baseTask.data?.activeGridDispatchPolicy || null,
        residentSequenceLaneContract: baseTask.data?.residentSequenceLaneContract || null,
        computeTaskSchema: baseTask.schema,
        lawGraphNodeId: baseTask.lawGraphNode?.nodeId || null
      },
      data: baseTask.data,
      webgpu: baseTask.webgpu
    });
  } catch (error) {
    const bridge = createMlsMpmResidentStepsSolverTaskBridgeMetadata(baseTask, null, {
      status: 'direct-ulg-task',
      reason: error instanceof Error ? error.message : String(error)
    });
    return {
      ...baseTask,
      peerComputeSolverTask: bridge,
      data: {
        ...baseTask.data,
        peerComputeSolverTask: bridge
      }
    };
  }

  const bridge = createMlsMpmResidentStepsSolverTaskBridgeMetadata(baseTask, solverTask);
  return {
    ...baseTask,
    ...solverTask,
    schema: baseTask.schema,
    id: baseTask.id,
    taskFamily: baseTask.taskFamily,
    solverId: baseTask.solverId,
    runtime: solverTask.runtime || baseTask.runtime,
    module: solverTask.module || baseTask.module,
    exportName: solverTask.exportName || baseTask.exportName,
    returnEnvelope: baseTask.returnEnvelope,
    suppressCommitDelta: baseTask.suppressCommitDelta,
    residency: baseTask.residency,
    lawGraphNode: baseTask.lawGraphNode,
    readFamilies: [...baseTask.readFamilies],
    writeFamilies: [...baseTask.writeFamilies],
    expectedOutputFamilies: [...baseTask.expectedOutputFamilies],
    webgpu: baseTask.webgpu,
    gpuFence: baseTask.gpuFence,
    gpuResidentLane: baseTask.gpuResidentLane,
    peerComputeSolverTask: bridge,
    data: {
      ...(solverTask.data || {}),
      ...baseTask.data,
      peerComputeSolverTask: bridge
    }
  };
}

export async function runMlsMpmResidentStepsComputeTask(data = {}) {
  const {
    gpuResidentLaneManager: _ignoredLaneManager,
    gpuFenceRequirement = null,
    gpuResidentLane = null,
    lawGraphNode = null,
    computeTaskSchema = ULG_MLS_MPM_RESIDENT_STEPS_COMPUTE_TASK_SCHEMA,
    computeTaskId = null,
    peerComputeSolverTask = null,
    activeGridDispatchPolicy = null,
    residentSequenceLaneContract = null,
    emitCommitDelta = true,
    commitDeltaScope = 'ulg-sph-resident-pass-dag',
    commitDeltaStateKey = null,
    expectedOutputFamilies = [],
    ...residentStepOptions
  } = data || {};
  const resolvedFenceRequirement = gpuFenceRequirement || gpuResidentLane || {};
  const fenceDevice = residentStepOptions.device || residentStepOptions.deviceResult?.device || null;
  const execution = await runMlsMpmResidentStepsWithOptionalWebGpu({
    ...residentStepOptions,
    gpuResidentLaneManager: null
  });
  await awaitResidentComputeTaskQueueFence(
    execution,
    resolvedFenceRequirement,
    fenceDevice
  );
  const gpuFence = createMlsMpmResidentStepGpuFenceReport(
    execution?.finalStep || execution,
    resolvedFenceRequirement
  );
  const result = {
    ...execution,
    schema: execution?.schema || ULG_MLS_MPM_GPU_RESIDENT_STEPS_EXECUTION_SCHEMA,
    computeTaskResultSchema: ULG_MLS_MPM_RESIDENT_STEPS_COMPUTE_TASK_RESULT_SCHEMA,
    computeTaskSchema,
    lawGraphNode,
    peerComputeSolverTask,
    activeGridDispatchPolicy,
    residentSequenceLaneContract,
    gpuFence,
    gpuFenceReport: gpuFence,
    gpuResidentLaneRequirement: gpuResidentLane || null
  };
  result.schroederAdoptedParticleStorageDescriptor =
    createSchroederAdoptedParticleStorageDescriptorFromStep(execution?.finalStep || execution, {
      gpuFence,
      stateKey: gpuFence?.stateKey || gpuResidentLane?.stateKey || commitDeltaStateKey || null,
      source: 'ulg-mls-mpm-resident-steps-compute-task',
      taskId: computeTaskId
    });
  result.schroederParticleStorageContinuationAvailable =
    result.schroederAdoptedParticleStorageDescriptor?.ready === true;
  result.schroederParticleStorageRawGpuBufferTransferDetected =
    result.schroederAdoptedParticleStorageDescriptor?.rawGpuBufferTransferDetected === true;
  if (emitCommitDelta !== false) {
    result.commitDelta = createMlsMpmResidentStepsCommitDelta(result, {
      taskId: computeTaskId,
      scope: commitDeltaScope,
      stateKey: commitDeltaStateKey,
      lawGraphNode,
      outputFamilies: expectedOutputFamilies,
      gpuResidentLane,
      residentSequenceLaneContract
    });
  }
  return result;
}

export function submitMlsMpmResidentStepsComputeTask({ computeManager, ...taskOptions } = {}) {
  if (!computeManager || typeof computeManager.submitTask !== 'function') {
    throw new Error('submitMlsMpmResidentStepsComputeTask requires a ComputeManager-compatible submitTask() method');
  }
  return computeManager.submitTask(createMlsMpmResidentStepsSolverComputeTask({
    computeManager,
    ...taskOptions
  }));
}

function createMlsMpmMechanicsP2gStageTaskEvidence(projection = {}, {
  computeTaskId = null,
  lawGraphNode = null,
  gpuFenceRequirement = null
} = {}) {
  const backend = projection?.backend || null;
  const acceptedBackend = ['cpu', 'cpu-reference', 'webgpu'].includes(String(backend || ''));
  const pressureSuppressed = finiteNumber(projection?.internalPressureScale, 1) === 0;
  const productSuppressed = finiteNumber(projection?.residentProductMassInputProductEventCount, 0) === 0
    && !projection?.residentProductMass;
  const gridNodeStrideBytes = finiteNumber(
    projection?.gridNodeStrideBytes,
    finiteNumber(projection?.gridNodeStrideFloats, 0) * Float32Array.BYTES_PER_ELEMENT
  );
  const gridProjected = projection?.status === 'projected'
    && finiteNumber(projection?.gridNodeCount, 0) > 0
    && gridNodeStrideBytes > 0;
  const passed = Boolean(
    projection
      && acceptedBackend
      && pressureSuppressed
      && productSuppressed
      && gridProjected
  );
  return {
    schema: ULG_MLS_MPM_MECHANICS_P2G_STAGE_TASK_EVIDENCE_SCHEMA,
    passed,
    status: passed ? 'mechanics-p2g-stage-task-evidence-ready' : 'mechanics-p2g-stage-task-evidence-failed',
    reason: passed
      ? 'compute-manager-owned-p2g-stage-task-ready'
      : !acceptedBackend
        ? 'mechanics-p2g-stage-task-backend-invalid'
        : !pressureSuppressed
          ? 'mechanics-p2g-stage-task-pressure-not-suppressed'
          : !productSuppressed
            ? 'mechanics-p2g-stage-task-product-input-not-suppressed'
            : 'mechanics-p2g-stage-task-grid-output-missing',
    computeTaskId,
    lawGraphNodeId: lawGraphNode?.nodeId || 'ulg-mls-mpm-mechanics-law',
    solverId: lawGraphNode?.solverId || 'ulg-mls-mpm-mechanics-p2g-stage',
    stageId: 'p2g',
    executionSource: 'runMlsMpmP2gGridProjectionWithOptionalWebGpu',
    backend,
    acceptedBackend,
    kernelScope: projection?.kernelScope || null,
    readbackMode: projection?.readbackMode || null,
    fullReadbackPerformed: projection?.fullReadbackPerformed === true,
    normalHotLoopReadbackFree: projection?.normalHotLoopReadbackFree === true,
    gridNodeCount: finiteNumber(projection?.gridNodeCount, 0),
    gridNodeStrideBytes,
    gridBufferRetained: Boolean(projection?.gridBuffer || projection?.gpuResult?.gridBuffer),
    pressureInterface: {
      suppressed: pressureSuppressed,
      internalPressureScale: finiteNumber(projection?.internalPressureScale, 1)
    },
    productInput: {
      suppressed: productSuppressed,
      productEventCount: finiteNumber(projection?.residentProductMassInputProductEventCount, 0),
      residentProductMassStatus: projection?.residentProductMassStatus || null
    },
    webgpuStatus: projection?.webgpuStatus ? { ...projection.webgpuStatus } : null,
    webgpuParityStatus: projection?.webgpuParity?.status || null,
    gpuFenceRequired: gpuFenceRequirement?.required === true,
    readFamilies: ['sph-particle-state', 'mls-mpm-mechanics'],
    transientWriteFamilies: ['mls-mpm-grid'],
    authoritativeWriteFamilies: [],
    mustNotWriteFamilies: ['sph-thermo-phase', 'resident-product-mass', 'pressure-interface-force-rows'],
    promotionStatus: 'stage-task-evidence-only-not-authoritative',
    scientificValidation: false,
    fullPhysicsValidation: false
  };
}

function createMlsMpmMechanicsP2gStageGpuFenceReport(projection = {}, requirement = {}) {
  const required = requirement?.required === true;
  const webgpuStatus = projection?.webgpuStatus?.status || null;
  const webgpuCompleted = projection?.backend !== 'webgpu'
    || projection?.fullReadbackPerformed === true
    || webgpuStatus === 'webgpu-executed'
    || webgpuStatus === 'webgpu-executed-no-full-readback';
  const fenceSatisfied = !required || webgpuCompleted;
  return {
    schema: PEERCOMPUTE_GPU_FENCE_REPORT_SCHEMA,
    required,
    fenceSatisfied,
    status: fenceSatisfied ? 'gpu-fence-satisfied' : 'gpu-fence-unsatisfied',
    reason: fenceSatisfied
      ? (required ? 'mechanics-p2g-stage-queue-completion-evidenced' : 'gpu-fence-not-required')
      : 'mechanics-p2g-stage-queue-completion-not-evidenced',
    laneId: requirement?.laneId || null,
    stateKey: requirement?.stateKey || null,
    source: 'ulg-mls-mpm-mechanics-p2g-stage-compute-task',
    backend: projection?.backend || null,
    webgpuStatus,
    readbackMode: projection?.readbackMode || null,
    fullReadbackPerformed: projection?.fullReadbackPerformed === true
  };
}

