function residentStepExecutedProductPlacementDispatch(step, expectedAccumulatorByteLength) {
  if (!(expectedAccumulatorByteLength > 0)) return false;
  const diagnostics = step?.diagnostics || {};
  const accumulatorByteLength = Number(
    diagnostics.reactionProductPlacementAccumulatorByteLength
  );
  if (accumulatorByteLength !== expectedAccumulatorByteLength) return false;
  const provenance = diagnostics.reactionProductPlacementProvenance;
  if (provenance?.available === true) return true;
  return diagnostics.reactionProductPlacementProvenanceStatus
    === 'product-placement-provenance-gpu-resident-not-read';
}

export async function runMlsMpmResidentStepsWithOptionalWebGpu({
  stepCount = 1,
  retainIntermediateSteps = false,
  compactSummaryMode = MLS_MPM_RESIDENT_COMPACT_SUMMARY_MODE_EVERY_STEP,
  compactSummaryScope = MLS_MPM_RESIDENT_SUMMARY_SCOPE_FULL,
  activeGridDispatchPlanRefreshMode = MLS_MPM_ACTIVE_GRID_PLAN_REFRESH_MODE_EVERY_STEP,
  onResidentStageProgress = null,
  ...args
} = {}) {
  const count = Math.max(1, Math.round(finiteNumber(stepCount, 1)));
  const canonicalSpatialIntent = args.canonicalSpatialRequired === true
    || args.schroederSpatialEpochGeneration?.selected === true;
  if (count > 1 && canonicalSpatialIntent) {
    const error = new Error(
      'Canonical spatial authority rejected before execution: one immutable hierarchy generation cannot span multiple position epochs'
    );
    error.code = 'ERR_CANONICAL_SPATIAL_AUTHORITY_REJECTED';
    error.status = 'canonical-spatial-generation-cannot-span-position-epochs';
    throw error;
  }
  const resolvedCompactSummaryMode = normalizeMlsMpmResidentCompactSummaryMode(compactSummaryMode);
  const resolvedCompactSummaryScope = normalizeMlsMpmResidentSummaryScope(compactSummaryScope);
  const resolvedActiveGridDispatchPlanRefreshMode = normalizeMlsMpmActiveGridPlanRefreshMode(
    activeGridDispatchPlanRefreshMode
  );
  let sphParticleState = args.sphParticleState;
  let mlsMpmParticleState = args.mlsMpmParticleState;
  let sphParticleUpload = args.sphParticleUpload ?? null;
  let mlsMpmParticleUpload = args.mlsMpmParticleUpload ?? null;
  let residentProductMass = args.residentProductMass ?? args.nextParticleUploads?.residentProductMass ?? null;
  let sourceSlot = args.sourceSlot ?? sphParticleUpload?.slot ?? 0;
  let finalStep = null;
  let pendingCompletedStep = null;
  const retainedSteps = [];
  const stepSummaries = [];
  const markSequenceProgress = (status, extra = {}) => {
    if (typeof onResidentStageProgress !== 'function') return;
    try {
      onResidentStageProgress({
        schema: 'peercompute.ulg.mls-mpm-resident-sequence-progress.v0',
        status,
        stepCount: count,
        compactSummaryMode: resolvedCompactSummaryMode,
        compactSummaryScope: resolvedCompactSummaryScope,
        activeGridDispatchPlanRefreshMode: resolvedActiveGridDispatchPlanRefreshMode,
        updatedAtMs: nowMs(),
        ...extra
      });
    } catch {
      // Diagnostic progress must never affect the physics sequence.
    }
  };

  markSequenceProgress('resident-sequence-started');

  const requestedReadbackMode = args.readbackMode === NO_FULL_READBACK_MODE ? NO_FULL_READBACK_MODE : FULL_READBACK_MODE;
  // A resident sequence is one device-owned transaction. Resolve an implicit
  // navigator request once so each substep cannot accidentally acquire and
  // relabel buffers for a different GPUDevice.
  if (args.preferWebGpu === true && !args.device && !args.deviceResult) {
    args.deviceResult = await requestOpticalGpuDevice(args.navigatorRef || globalThis.navigator);
  }
  const resolvedDevice = args.device || args.deviceResult?.device || null;
  const requestActiveGridFusedNoFullMechanics = Boolean(
    args.fuseNoFullResidentMechanicsActiveGrid || args.fuseNoFullResidentActiveGrid
  );
  const requestPerStepFusedNoFullMechanics = Boolean(
    args.fuseNoFullResidentMechanics
    || (args.fuseNoFullResidentMechanicsSequence && requestActiveGridFusedNoFullMechanics)
  );
  const fusedSequenceCustomRunnerBlockers = [
    args.p2gRunner ? 'custom-p2g-runner' : null,
    args.gridUpdateRunner ? 'custom-grid-update-runner' : null,
    args.g2pRunner ? 'custom-g2p-runner' : null,
    args.p2gStageRunner ? 'custom-p2g-stage-runner' : null,
    args.gridUpdateStageRunner ? 'custom-grid-update-stage-runner' : null,
    args.g2pStageRunner ? 'custom-g2p-stage-runner' : null,
    canonicalSpatialIntent ? 'canonical-spatial-single-step-executor-required' : null
  ];
  const fusedResidentSequencePreflight = createFusedResidentSequencePreflight({
    requested: Boolean(args.fuseNoFullResidentMechanicsSequence),
    stepCount: count,
    readbackMode: requestedReadbackMode,
    compactSummaryMode: resolvedCompactSummaryMode,
    preferWebGpu: args.preferWebGpu === true,
    device: resolvedDevice,
    sphParticleUpload,
    mlsMpmParticleUpload,
    requestPerStepFusedNoFullMechanics,
    requestActiveGridFusedNoFullMechanics,
    customRunnerBlockers: fusedSequenceCustomRunnerBlockers,
    sidecarBlockers: fusedResidentSequenceSidecarBlockers({
      thermalMaterialTable: args.thermalMaterialTable,
      reactionTable: args.reactionTable,
      pressureInterfaceForceRowsBuffer: args.pressureInterfaceForceRowsBuffer,
      pressureInterfaceForceSolver: args.pressureInterfaceForceSolver,
      residentProductMass,
      phaseCarrierPlan: sphParticleUpload?.phaseCarrierPlan
        || sphParticleState?.phaseCarrierPlan
        || null
    }),
    thermalSidecarFusionAvailable: Boolean(
      args.fuseThermalSidecarResidentSequence !== false
      && args.thermalMaterialTable
      && args.mechanicsMaterialTable
      && (args.thermalStepRunner == null || args.thermalStepRunner === runSphThermalStepWebGpu)
      && (
        args.mechanicsRefreshRunner == null
        || args.mechanicsRefreshRunner === runMlsMpmMechanicsRefreshWithOptionalWebGpu
      )
    )
  });
  const sidecarAwareDirectRunnerContract = createThermalSidecarDirectRunnerContract({
    preflight: fusedResidentSequencePreflight,
    thermalMaterialTable: args.thermalMaterialTable,
    mechanicsMaterialTable: args.mechanicsMaterialTable,
    thermalStepRunner: args.thermalStepRunner ?? runSphThermalStepWebGpu,
    mechanicsRefreshRunner: args.mechanicsRefreshRunner ?? runMlsMpmMechanicsRefreshWithOptionalWebGpu,
    reactionTable: args.reactionTable,
    pressureInterfaceForceRowsBuffer: args.pressureInterfaceForceRowsBuffer,
    pressureInterfaceForceSolver: args.pressureInterfaceForceSolver,
    residentProductMass,
    gpuResidentLaneManager: args.gpuResidentLaneManager,
    directRunnerImplementationAvailable: true
  });
  fusedResidentSequencePreflight.sidecarAwareDirectRunnerContract = sidecarAwareDirectRunnerContract;
  fusedResidentSequencePreflight.sidecarAwareDirectRunnerContractStatus = sidecarAwareDirectRunnerContract.status;
  fusedResidentSequencePreflight.sidecarAwareDirectRunnerEligible = sidecarAwareDirectRunnerContract.directRunnerEligible;
  fusedResidentSequencePreflight.sidecarAwareDirectRunnerRunnable = sidecarAwareDirectRunnerContract.directRunnerRunnable;
  fusedResidentSequencePreflight.sidecarAwareDirectRunnerSelected = sidecarAwareDirectRunnerContract.directRunnerSelected;
  fusedResidentSequencePreflight.sidecarAwareDirectRunnerSelectionStatus =
    sidecarAwareDirectRunnerContract.directRunnerSelectionStatus;
  const useFusedNoFullResidentMechanicsSequence = fusedResidentSequencePreflight.sequenceRunnable === true;
  if (useFusedNoFullResidentMechanicsSequence) {
    markSequenceProgress('resident-sequence-fused-mechanics-started', {
      stepCount: count
    });
    const finalStep = await runFusedNoFullMlsMpmMechanicsSequenceWebGpu({
      device: resolvedDevice,
      sphParticleState,
      mlsMpmParticleState,
      sphParticleUpload,
      mlsMpmParticleUpload,
      gridSpacingM: args.gridSpacingM,
      boxDimsM: args.boxDimsM,
      dt: args.dt,
      gravityMPerS2: args.gravityMPerS2,
      cflFactor: args.cflFactor,
      internalPressureScale: args.internalPressureScale,
      ambientPressurePa: args.ambientPressurePa,
      stepCount: count,
      summaryRunner: compactSummaryModeRequestsReadback(resolvedCompactSummaryMode)
        ? (args.summaryRunner ?? runMlsMpmResidentSummaryWebGpu)
        : null,
      compactSummaryScope: resolvedCompactSummaryScope,
      cohortRanges: args.cohortRanges ?? null,
      sourceSlot,
      preferWebGpu: args.preferWebGpu,
      fuseActiveGrid: Boolean(args.fuseNoFullResidentMechanicsActiveGrid || args.fuseNoFullResidentActiveGrid),
      activeGridSafetyCells: args.fusedActiveGridSafetyCells ?? args.activeGridSafetyCells,
      p2gBackend: args.p2gBackend ?? MLS_MPM_P2G_BACKEND_RESIDENT_SCATTER,
      schroederLevelAssignment: args.schroederLevelAssignment ?? null,
      schroederSelectedLevel: args.schroederSelectedLevel ?? null,
      schroederActiveNodeList: args.schroederActiveNodeList ?? null,
      schroederSpatialEpochGeneration: args.schroederSpatialEpochGeneration ?? null,
      canonicalSpatialRequired: args.canonicalSpatialRequired === true,
      measureQueueFence: Boolean(
        args.measureFusedSequenceQueueFence
        || args.measureGpuQueueFence
        || args.benchmarkQueueFence
      ),
      sidecarFusionPlan: fusedResidentSequencePreflight.sidecarFusionPlan,
      thermalMaterialTable: args.thermalMaterialTable,
      thermalStepOptions: args.thermalStepOptions ?? {},
      mechanicsMaterialTable: args.mechanicsMaterialTable,
      mechanicsRefreshOptions: args.mechanicsRefreshOptions ?? {},
      // PROF-0. Opt-in per run. The device must also have been created with
      // 'timestamp-query' (webgpuDeviceLimits.js negotiates it); the profiler
      // stays inert and says so if it was not.
      residentGpuTimestampProfilingRequested:
        args.residentGpuTimestampProfilingRequested === true
    });
    const nextSphParticleState = cloneSphParticleStateForNext(sphParticleState, finalStep);
    const nextMlsMpmParticleState = cloneMlsMpmParticleStateForNext(mlsMpmParticleState, finalStep);
    finalStep.fusedResidentSequencePreflight = fusedResidentSequencePreflight;
    if (finalStep.stageTiming) {
      finalStep.stageTiming.fusedResidentSequencePreflight = fusedResidentSequencePreflight;
    }
    const stepSummaries = Array.from({ length: count }, (_, index) => {
      const summary = summarizeResidentStepForSequence(finalStep, index);
      summary.status = index === count - 1
        ? finalStep.status
        : 'resident-step-fused-sequence-intermediate';
      summary.fusedResidentSequence = true;
      summary.fusedResidentSequenceStepCount = count;
      summary.compactSummaryMode = resolvedCompactSummaryMode;
      summary.compactSummaryAvailable = compactSummaryModeRequestsReadback(resolvedCompactSummaryMode)
        && index === count - 1;
      return summary;
    });
    markSequenceProgress('resident-sequence-fused-mechanics-complete', {
      completedStepCount: count,
      backend: finalStep.backend,
      stageTiming: finalStep.stageTiming || null
    });
    return {
      schema: ULG_MLS_MPM_GPU_RESIDENT_STEPS_EXECUTION_SCHEMA,
      backend: finalStep.backend || 'webgpu',
      status: 'resident-steps-executed',
      // PROF-0. Device execution time per stage, next to the host-timeline
      // stageMs. Null when profiling was inert; gpuTimestampProfile.status says
      // which of "not requested", "unsupported by device" or "read failed"
      // applies, so an absent measurement is never mistaken for a zero one.
      stageGpuMs: finalStep.stageGpuMs ?? null,
      gpuTimestampProfile: finalStep.gpuTimestampProfile ?? null,
      stepCount: count,
      completedStepCount: count,
      compactSummaryMode: resolvedCompactSummaryMode,
      compactSummaryScope: resolvedCompactSummaryScope,
      activeGridDispatchPlanRefreshMode: resolvedActiveGridDispatchPlanRefreshMode,
      retainIntermediateSteps,
      retainedIntermediateStepCount: 0,
      retainedSteps,
      finalStep,
      stepSummaries,
      ambientPressurePa: Math.max(0, finiteNumber(finalStep.ambientPressurePa, 0)),
      ambientPressureAppliedInStressProjection:
        finalStep.ambientPressureAppliedInStressProjection === true,
      nextSphParticleState,
      nextMlsMpmParticleState,
      nextParticleUploads: finalStep.nextParticleUploads ?? null,
      nextResidentProductMass: null,
      nextParticleBufferMode: finalStep.nextParticleBufferMode ?? 'not-available',
      readbackMode: finalStep.readbackMode ?? NO_FULL_READBACK_MODE,
      fullParticleReadbackPerformed:
        finalStep.fullParticleReadbackPerformed === true,
      normalHotLoopReadbackFree: Boolean(finalStep.normalHotLoopReadbackFree),
      renderStateReadbackAvailable: finalStep.renderStateReadbackAvailable ?? false,
      residentAuthorityLedgerStatus: finalStep.residentAuthorityLedgerStatus ?? null,
      residentAuthorityFamilyOwners: compactResidentAuthorityFamilyOwners(
        finalStep.residentAuthorityFamilyOwners || finalStep.residentAuthoritySummary?.familyOwners
      ),
      residentAuthorityWarnings: [...(finalStep.residentAuthorityWarnings || [])],
      residentAuthorityBlockers: [...(finalStep.residentAuthorityBlockers || [])],
      residentBufferLeaseLedgerStatus: finalStep.residentBufferLeaseLedgerStatus ?? null,
      residentBufferLeaseResourceCount: finalStep.residentBufferLeaseResourceCount ?? 0,
      residentBufferLeaseActiveLeaseCount: finalStep.residentBufferLeaseActiveLeaseCount ?? 0,
      residentBufferLeaseWarnings: [...(finalStep.residentBufferLeaseWarnings || [])],
      residentBufferLeaseBlockers: [...(finalStep.residentBufferLeaseBlockers || [])],
      fusedResidentSequence: finalStep.fusedResidentSequence,
      fusedResidentSequencePreflight,
      sidecarAwareResidentSequenceActive: false,
      sidecarAwareResidentSequenceMode: null,
      sidecarAwareResidentSequenceRunner: null,
      sidecarAwareResidentSequencePath: null,
      sidecarAwareDirectRunnerContract,
      sidecarAwareDirectRunnerContractStatus: sidecarAwareDirectRunnerContract.status,
      sidecarAwareResidentSequence: null,
      sidecarAwareResidentSequenceStatus: null,
      gpuAuthoritativeState: false,
      scientificValidation: false,
      sphValidation: false,
      phaseChangeValidation: false,
      fullPhysicsValidation: false
    };
  }

  const useSidecarAwareResidentSequence = fusedResidentSequencePreflight.sidecarAwareSequenceCandidate === true;
  const useThermalSidecarDirectRunner = useSidecarAwareResidentSequence
    && sidecarAwareDirectRunnerContract.directRunnerSelected === true;
  if (useSidecarAwareResidentSequence) {
    markSequenceProgress(useThermalSidecarDirectRunner
      ? 'resident-sequence-thermal-sidecar-direct-runner-started'
      : 'resident-sequence-sidecar-aware-started', {
      stepCount: count,
      mode: fusedResidentSequencePreflight.sidecarAwareSequenceMode ?? null,
      runner: fusedResidentSequencePreflight.sidecarAwareSequenceRunner ?? null,
      sequencePath: fusedResidentSequencePreflight.sidecarAwareSequencePath ?? null,
      directRunnerContractStatus: sidecarAwareDirectRunnerContract.status,
      directRunnerSelected: useThermalSidecarDirectRunner
    });
  }

  // Placement provenance is accumulated on-device for exactly this resident
  // sequence. Intermediate reaction substeps only write the accumulator; the
  // final substep performs the compact readback. Keeping this ownership out of
  // resident-product handles avoids per-step replacement/double-destroy races.
  const productPlacementAccumulatorByteLength = Math.max(
    0,
    Math.round(Number(args.reactionTable?.productTermCount) || 0)
      * SPH_GPU_REACTION_PRODUCT_PLACEMENT_SUMMARY_FLOATS
      * Float32Array.BYTES_PER_ELEMENT
  );
  const suppliedProductPlacementAccumulator =
    args.reactionStepOptions?.productPlacementAccumulatorBuffer ?? null;
  const shouldAccumulateProductPlacement = requestedReadbackMode === NO_FULL_READBACK_MODE
    && args.preferWebGpu === true
    && (args.reactionTable?.reactionCount ?? 0) > 0
    && Boolean(args.thermalMaterialTable)
    && Boolean(resolvedDevice?.createBuffer)
    && Boolean(resolvedDevice?.queue?.writeBuffer)
    && productPlacementAccumulatorByteLength > 0;
  const productPlacementAccumulatorBuffer = shouldAccumulateProductPlacement
    ? (suppliedProductPlacementAccumulator || tagWebGpuBufferDevice(resolvedDevice.createBuffer({
        label: 'ulg-sph-reaction-product-placement-resident-sequence-accumulator',
        size: Math.max(4, productPlacementAccumulatorByteLength),
        usage: GPU_BUFFER_USAGE.STORAGE | GPU_BUFFER_USAGE.COPY_SRC | GPU_BUFFER_USAGE.COPY_DST
      }), resolvedDevice))
    : suppliedProductPlacementAccumulator;
  const ownsProductPlacementAccumulator = Boolean(
    shouldAccumulateProductPlacement
    && productPlacementAccumulatorBuffer
    && !suppliedProductPlacementAccumulator
  );
  let productPlacementAccumulatorDestroyed = false;
  const destroyOwnedProductPlacementAccumulator = () => {
    if (!ownsProductPlacementAccumulator || productPlacementAccumulatorDestroyed) return;
    productPlacementAccumulatorDestroyed = true;
    productPlacementAccumulatorBuffer.destroy?.();
  };
  if (ownsProductPlacementAccumulator) {
    resolvedDevice.queue.writeBuffer(
      productPlacementAccumulatorBuffer,
      0,
      new Uint8Array(productPlacementAccumulatorByteLength)
    );
  }
  let productPlacementSuccessfulDispatchCount = 0;
  let productPlacementDispatchEvidenceComplete = true;

  try {
    for (let index = 0; index < count; index += 1) {
    const summarizeStep = compactSummaryModeRequestsReadback(resolvedCompactSummaryMode)
      && (resolvedCompactSummaryMode !== MLS_MPM_RESIDENT_COMPACT_SUMMARY_MODE_FINAL_ONLY || index === count - 1);
    markSequenceProgress(useThermalSidecarDirectRunner
      ? 'resident-sequence-thermal-sidecar-direct-runner-step-started'
      : (useSidecarAwareResidentSequence
      ? 'resident-sequence-sidecar-aware-step-started'
      : 'resident-sequence-step-started'), {
      stepIndex: index,
      summarizeStep,
      sidecarAwareSequenceMode: useSidecarAwareResidentSequence
        ? fusedResidentSequencePreflight.sidecarAwareSequenceMode
        : null,
      sidecarAwareDirectRunnerContractStatus: useSidecarAwareResidentSequence
        ? sidecarAwareDirectRunnerContract.status
        : null,
      directRunnerSelected: useThermalSidecarDirectRunner
    });
    const stepArgs = {
      ...args,
      sphParticleState,
      mlsMpmParticleState,
      sphParticleUpload,
      mlsMpmParticleUpload,
      residentProductMass,
      sourceSlot,
      compactSummaryScope: resolvedCompactSummaryScope,
      fuseNoFullResidentMechanics: requestPerStepFusedNoFullMechanics,
      activeGridDispatchPlanRefreshMode: resolvedActiveGridDispatchPlanRefreshMode,
      sidecarFusionPlan: fusedResidentSequencePreflight.sidecarFusionPlan || null,
      sidecarAwareSequenceMode: useSidecarAwareResidentSequence
        ? fusedResidentSequencePreflight.sidecarAwareSequenceMode
        : null,
      sidecarAwareDirectRunnerContract: useSidecarAwareResidentSequence
        ? sidecarAwareDirectRunnerContract
        : null,
      sequenceIndex: index,
      sequenceStepCount: count,
      reactionStepOptions: {
        ...(args.reactionStepOptions || {}),
        // The resident hot loop keeps full particle state on the GPU, but the
        // pressure-force safety gate still needs one fixed-size reaction
        // ledger and atom-residual proof per presented batch.  Without these
        // final-only reads every no-full sequence reports
        // `strict-reaction-gate-not-run-resident-no-readback`, so chemically
        // produced H2 can raise the pressure ledger while mechanics is forced
        // to apply zero impulse.
        readCompactReactionSummary: summarizeStep,
        readReactionGasSpeciesSummary: summarizeStep,
        readReactionProductInventory: summarizeStep,
        readReactionAtomResidual: summarizeStep,
        ...(productPlacementAccumulatorBuffer ? {
          productPlacementAccumulatorBuffer,
          readReactionProductPlacementSummary: index === count - 1,
          reactionProductPlacementReadbackCadence: 'resident-sequence-final-only',
          // Count only prior dispatches proven by returned step evidence. The
          // current dispatch is included because a decoded final provenance
          // row can only exist after this call's placement pass ran.
          reactionProductPlacementSourceSummaryCount:
            productPlacementSuccessfulDispatchCount + 1
        } : {})
      },
      onResidentStageProgress(progress = {}) {
        markSequenceProgress(progress.status || 'resident-stage-progress', {
          ...progress,
          stepIndex: progress.stepIndex ?? progress.sequenceIndex ?? index,
          summarizeStep,
          sidecarAwareSequenceMode: useSidecarAwareResidentSequence
            ? fusedResidentSequencePreflight.sidecarAwareSequenceMode
            : null,
          sidecarAwareDirectRunnerContractStatus: useSidecarAwareResidentSequence
            ? sidecarAwareDirectRunnerContract.status
            : null
        });
      }
    };
    if (!summarizeStep) stepArgs.summaryRunner = null;
    const step = useThermalSidecarDirectRunner
      ? await runThermalSidecarDirectResidentStepWithOptionalWebGpu(stepArgs)
      : await runMlsMpmResidentStepWithOptionalWebGpu(stepArgs);
    pendingCompletedStep = step;
    step.sequenceIndex = index;
    step.sidecarAwareResidentSequenceActive = useSidecarAwareResidentSequence;
    step.sidecarAwareResidentSequenceMode = useSidecarAwareResidentSequence
      ? fusedResidentSequencePreflight.sidecarAwareSequenceMode
      : null;
    step.sidecarAwareResidentSequenceRunner = useSidecarAwareResidentSequence
      ? fusedResidentSequencePreflight.sidecarAwareSequenceRunner
      : null;
    step.sidecarAwareResidentSequencePath = useSidecarAwareResidentSequence
      ? fusedResidentSequencePreflight.sidecarAwareSequencePath
      : null;
    step.sidecarAwareDirectRunnerContract = useSidecarAwareResidentSequence
      ? sidecarAwareDirectRunnerContract
      : null;
    step.sidecarAwareDirectRunnerContractStatus = useSidecarAwareResidentSequence
      ? sidecarAwareDirectRunnerContract.status
      : null;
    if (step.stageTiming && useSidecarAwareResidentSequence) {
      step.stageTiming.sidecarAwareResidentSequenceActive = true;
      step.stageTiming.sidecarAwareResidentSequenceMode = fusedResidentSequencePreflight.sidecarAwareSequenceMode;
      step.stageTiming.sidecarAwareResidentSequenceRunner = fusedResidentSequencePreflight.sidecarAwareSequenceRunner;
      step.stageTiming.sidecarAwareResidentSequencePath = fusedResidentSequencePreflight.sidecarAwareSequencePath;
      step.stageTiming.sidecarAwareResidentSequenceStepIndex = index;
      step.stageTiming.sidecarAwareResidentSequenceStepCount = count;
      step.stageTiming.sidecarAwareDirectRunnerContract = sidecarAwareDirectRunnerContract;
      step.stageTiming.sidecarAwareDirectRunnerContractStatus = sidecarAwareDirectRunnerContract.status;
      step.stageTiming.sidecarAwareDirectRunnerSelected = useThermalSidecarDirectRunner;
    }
    const productPlacementDispatchProven = residentStepExecutedProductPlacementDispatch(
      step,
      productPlacementAccumulatorByteLength
    );
    if (productPlacementDispatchProven) {
      productPlacementSuccessfulDispatchCount += 1;
    } else if (productPlacementAccumulatorBuffer && productPlacementAccumulatorByteLength > 0) {
      // The GPU may have written the shared accumulator before a later
      // diagnostic/map failure removed the returned evidence. Once that
      // happens no host-derived source count can certify the buffer contents.
      productPlacementDispatchEvidenceComplete = false;
    }
    stepSummaries.push(summarizeResidentStepForSequence(step, index));
    markSequenceProgress(useThermalSidecarDirectRunner
      ? 'resident-sequence-thermal-sidecar-direct-runner-step-complete'
      : (useSidecarAwareResidentSequence
      ? 'resident-sequence-sidecar-aware-step-complete'
      : 'resident-sequence-step-complete'), {
      stepIndex: index,
      summarizeStep,
      backend: step.backend,
      stageTiming: step.stageTiming || null,
      sidecarAwareSequenceMode: useSidecarAwareResidentSequence
        ? fusedResidentSequencePreflight.sidecarAwareSequenceMode
        : null,
      sidecarAwareDirectRunnerContractStatus: useSidecarAwareResidentSequence
        ? sidecarAwareDirectRunnerContract.status
        : null,
      directRunnerSelected: useThermalSidecarDirectRunner
    });
    const carriedResidentProductMass = step.nextParticleUploads?.residentProductMass ?? step.residentProductMass ?? null;
    if (finalStep && !retainIntermediateSteps) {
      destroyMlsMpmResidentStepBuffers(finalStep, {
        preserveResidentProductMass: carriedResidentProductMass,
        preserveResidentProductMassHandles: [
          step.emittedResidentProductMass,
          carriedResidentProductMass
        ].filter(Boolean),
        destroyInputResidentProductMass: true,
        preserveBuffers: retainedContinuationBuffersFromUploads(step.nextParticleUploads)
      });
    } else if (finalStep) {
      retainedSteps.push(finalStep);
    }
    finalStep = step;
    pendingCompletedStep = null;
    sphParticleState = cloneSphParticleStateForNext(sphParticleState, step);
    mlsMpmParticleState = cloneMlsMpmParticleStateForNext(mlsMpmParticleState, step);
    sphParticleUpload = step.nextParticleUploads?.sphParticleUpload ?? null;
    mlsMpmParticleUpload = step.nextParticleUploads?.mlsMpmParticleUpload ?? null;
    residentProductMass = carriedResidentProductMass;
    sourceSlot = step.particlePingPong?.nextSlot ?? (sourceSlot === 0 ? 1 : 0);
    }
  } catch (error) {
    const cleanupErrors = [];
    const abortedSteps = [
      ...retainedSteps,
      finalStep,
      pendingCompletedStep
    ].filter(Boolean);
    const cleanedSteps = new Set();
    for (const abortedStep of abortedSteps) {
      if (cleanedSteps.has(abortedStep)) continue;
      cleanedSteps.add(abortedStep);
      try {
        destroyMlsMpmResidentStepBuffers(abortedStep, {
          destroyInputResidentProductMass: true
        });
      } catch (cleanupError) {
        cleanupErrors.push(cleanupError);
      }
    }
    retainedSteps.length = 0;
    finalStep = null;
    pendingCompletedStep = null;
    if (ownsProductPlacementAccumulator) {
      deferSubmittedWorkCleanup(resolvedDevice, destroyOwnedProductPlacementAccumulator);
    }
    if (cleanupErrors.length > 0 && error && typeof error === 'object') {
      error.residentSequenceCleanupErrors = cleanupErrors;
    }
    throw error;
  }

  const sidecarAwareResidentSequence = createSidecarAwareResidentSequenceEvidence({
    preflight: fusedResidentSequencePreflight,
    stepSummaries,
    completedStepCount: stepSummaries.length
  });
  if (finalStep && sidecarAwareResidentSequence) {
    finalStep.sidecarAwareResidentSequence = sidecarAwareResidentSequence;
    finalStep.sidecarAwareResidentSequenceStatus = sidecarAwareResidentSequence.status;
    finalStep.sidecarAwareDirectRunnerContract = sidecarAwareDirectRunnerContract;
    finalStep.sidecarAwareDirectRunnerContractStatus = sidecarAwareDirectRunnerContract.status;
    finalStep.sidecarAwareDirectRunnerSelected = useThermalSidecarDirectRunner;
    if (finalStep.stageTiming) {
      finalStep.stageTiming.sidecarAwareResidentSequence = sidecarAwareResidentSequence;
      finalStep.stageTiming.sidecarAwareResidentSequenceStatus = sidecarAwareResidentSequence.status;
      finalStep.stageTiming.sidecarAwareDirectRunnerContract = sidecarAwareDirectRunnerContract;
      finalStep.stageTiming.sidecarAwareDirectRunnerContractStatus = sidecarAwareDirectRunnerContract.status;
      finalStep.stageTiming.sidecarAwareDirectRunnerSelected = useThermalSidecarDirectRunner;
    }
  }

  markSequenceProgress('resident-sequence-complete', {
    completedStepCount: stepSummaries.length,
    backend: finalStep?.backend || 'cpu-reference',
    sidecarAwareResidentSequenceStatus: sidecarAwareResidentSequence?.status ?? null
  });
  if (useSidecarAwareResidentSequence) {
    markSequenceProgress(useThermalSidecarDirectRunner
      ? 'resident-sequence-thermal-sidecar-direct-runner-complete'
      : 'resident-sequence-sidecar-aware-complete', {
      completedStepCount: stepSummaries.length,
      backend: finalStep?.backend || 'cpu-reference',
      mode: fusedResidentSequencePreflight.sidecarAwareSequenceMode ?? null,
      runner: fusedResidentSequencePreflight.sidecarAwareSequenceRunner ?? null,
      sequencePath: fusedResidentSequencePreflight.sidecarAwareSequencePath ?? null,
      directRunnerContractStatus: sidecarAwareDirectRunnerContract.status,
      directRunnerSelected: useThermalSidecarDirectRunner,
      sidecarAwareResidentSequenceStatus: sidecarAwareResidentSequence?.status ?? null
    });
  }
  if (finalStep && fusedResidentSequencePreflight.sequenceRequested) {
    finalStep.fusedResidentSequencePreflight = fusedResidentSequencePreflight;
    if (finalStep.stageTiming) {
      finalStep.stageTiming.fusedResidentSequencePreflight = fusedResidentSequencePreflight;
    }
  }

  const finalReactionResult = finalStep?.reactionStep?.result || finalStep?.reactionStep || null;
  const rawFinalProductPlacementProvenance =
    finalStep?.diagnostics?.reactionProductPlacementProvenance
    || finalReactionResult?.reactionSummary?.productPlacementProvenance
    || null;
  const finalProductPlacementSourceCountVerified = Boolean(
    productPlacementAccumulatorBuffer
    && productPlacementDispatchEvidenceComplete
    && rawFinalProductPlacementProvenance?.available === true
    && productPlacementSuccessfulDispatchCount === count
    && Number(rawFinalProductPlacementProvenance.sourceSummaryCount)
      === productPlacementSuccessfulDispatchCount
  );
  const finalProductPlacementProvenance = finalProductPlacementSourceCountVerified
    ? rawFinalProductPlacementProvenance
    : null;
  const productPlacementEvidenceIncomplete = Boolean(
    productPlacementAccumulatorBuffer
    && productPlacementAccumulatorByteLength > 0
    && !productPlacementDispatchEvidenceComplete
  );
  if (productPlacementEvidenceIncomplete) {
    const status = 'resident-sequence-product-placement-dispatch-evidence-incomplete';
    if (finalStep?.diagnostics) {
      finalStep.diagnostics.reactionProductPlacementProvenance = null;
      finalStep.diagnostics.reactionProductPlacementProvenanceStatus = status;
      finalStep.diagnostics.reactionProductPlacementMechanicsRefreshStatus =
        'product-placement-provenance-not-available-unproven-sequence';
      finalStep.diagnostics.reactionProductPlacementMechanicsRefreshCarried = false;
    }
    if (finalStep) {
      finalStep.reactionProductPlacementMechanicsRefreshStatus =
        'product-placement-provenance-not-available-unproven-sequence';
      finalStep.reactionProductPlacementMechanicsRefreshCarried = false;
    }
    if (finalReactionResult?.reactionSummary) {
      finalReactionResult.reactionSummary.productPlacementProvenance = null;
      finalReactionResult.reactionSummary.productPlacementProvenanceStatus = status;
    }
    const finalStepSummaryDiagnostics = stepSummaries.at(-1)?.diagnostics;
    if (finalStepSummaryDiagnostics) {
      finalStepSummaryDiagnostics.reactionProductPlacementProvenance = null;
      finalStepSummaryDiagnostics.reactionProductPlacementProvenanceStatus = status;
      finalStepSummaryDiagnostics.reactionProductPlacementMechanicsRefreshStatus =
        'product-placement-provenance-not-available-unproven-sequence';
      finalStepSummaryDiagnostics.reactionProductPlacementMechanicsRefreshCarried = false;
    }
  }
  if (ownsProductPlacementAccumulator) {
    deferSubmittedWorkCleanup(resolvedDevice, destroyOwnedProductPlacementAccumulator);
  }

  return {
    schema: ULG_MLS_MPM_GPU_RESIDENT_STEPS_EXECUTION_SCHEMA,
    backend: finalStep?.backend || 'cpu-reference',
    status: 'resident-steps-executed',
    stepCount: count,
    completedStepCount: stepSummaries.length,
    compactSummaryMode: resolvedCompactSummaryMode,
    compactSummaryScope: resolvedCompactSummaryScope,
    activeGridDispatchPlanRefreshMode: resolvedActiveGridDispatchPlanRefreshMode,
    retainIntermediateSteps,
    retainedIntermediateStepCount: retainedSteps.length,
    retainedSteps,
    finalStep,
    stepSummaries,
    ambientPressurePa: Math.max(0, finiteNumber(finalStep?.ambientPressurePa, 0)),
    ambientPressureAppliedInStressProjection:
      finalStep?.ambientPressureAppliedInStressProjection === true,
    nextSphParticleState: sphParticleState,
    nextMlsMpmParticleState: mlsMpmParticleState,
    nextParticleUploads: finalStep?.nextParticleUploads ?? null,
    nextResidentProductMass: residentProductMass,
    nextParticleBufferMode: finalStep?.nextParticleBufferMode ?? 'not-available',
    readbackMode: finalStep?.readbackMode ?? FULL_READBACK_MODE,
    fullParticleReadbackPerformed:
      finalStep?.fullParticleReadbackPerformed === true,
    normalHotLoopReadbackFree: Boolean(finalStep?.normalHotLoopReadbackFree),
    renderStateReadbackAvailable: finalStep?.renderStateReadbackAvailable ?? true,
    residentAuthorityLedgerStatus: finalStep?.residentAuthorityLedgerStatus ?? null,
    residentAuthorityFamilyOwners: compactResidentAuthorityFamilyOwners(
      finalStep?.residentAuthorityFamilyOwners || finalStep?.residentAuthoritySummary?.familyOwners
    ),
    residentAuthorityWarnings: [...(finalStep?.residentAuthorityWarnings || [])],
    residentAuthorityBlockers: [...(finalStep?.residentAuthorityBlockers || [])],
    residentBufferLeaseLedgerStatus: finalStep?.residentBufferLeaseLedgerStatus ?? null,
    residentBufferLeaseResourceCount: finalStep?.residentBufferLeaseResourceCount ?? 0,
    residentBufferLeaseActiveLeaseCount: finalStep?.residentBufferLeaseActiveLeaseCount ?? 0,
    residentBufferLeaseWarnings: [...(finalStep?.residentBufferLeaseWarnings || [])],
    residentBufferLeaseBlockers: [...(finalStep?.residentBufferLeaseBlockers || [])],
    reactionProductPlacementAccumulatorStatus: finalProductPlacementProvenance?.status
      ?? (productPlacementEvidenceIncomplete
          ? 'resident-sequence-product-placement-dispatch-evidence-incomplete'
          : (rawFinalProductPlacementProvenance
          ? 'resident-sequence-product-placement-source-count-unproven'
          : (productPlacementAccumulatorBuffer
          ? 'resident-sequence-product-placement-accumulator-not-read'
          : 'resident-sequence-product-placement-accumulator-not-run'))),
    reactionProductPlacementAccumulatorByteLength: productPlacementAccumulatorBuffer
      ? productPlacementAccumulatorByteLength
      : 0,
    reactionProductPlacementAccumulatorOwned: ownsProductPlacementAccumulator,
    reactionProductPlacementReadbackCadence: productPlacementAccumulatorBuffer
      ? 'resident-sequence-final-only'
      : null,
    reactionProductPlacementSuccessfulDispatchCount:
      productPlacementSuccessfulDispatchCount,
    reactionProductPlacementDispatchEvidenceComplete:
      productPlacementAccumulatorBuffer && productPlacementAccumulatorByteLength > 0
        ? productPlacementDispatchEvidenceComplete
        : null,
    reactionProductPlacementSourceCountVerified:
      finalProductPlacementSourceCountVerified,
    reactionProductPlacementProvenance: finalProductPlacementProvenance
      ? {
          ...finalProductPlacementProvenance,
          records: (finalProductPlacementProvenance.records || []).map((row) => ({ ...row })),
          byMaterial: Object.fromEntries(
            Object.entries(finalProductPlacementProvenance.byMaterial || {})
              .map(([key, row]) => [key, {
                ...row,
                productTermIndices: [...(row.productTermIndices || [])]
              }])
          )
        }
      : null,
    fusedResidentSequencePreflight,
    sidecarAwareResidentSequenceActive: useSidecarAwareResidentSequence,
    sidecarAwareResidentSequenceMode: useSidecarAwareResidentSequence
      ? fusedResidentSequencePreflight.sidecarAwareSequenceMode
      : null,
    sidecarAwareResidentSequenceRunner: useSidecarAwareResidentSequence
      ? fusedResidentSequencePreflight.sidecarAwareSequenceRunner
      : null,
    sidecarAwareResidentSequencePath: useSidecarAwareResidentSequence
      ? fusedResidentSequencePreflight.sidecarAwareSequencePath
      : null,
    sidecarAwareDirectRunnerContract,
    sidecarAwareDirectRunnerContractStatus: sidecarAwareDirectRunnerContract.status,
    sidecarAwareDirectRunnerEligible: sidecarAwareDirectRunnerContract.directRunnerEligible,
    sidecarAwareDirectRunnerRunnable: sidecarAwareDirectRunnerContract.directRunnerRunnable,
    sidecarAwareDirectRunnerSelected: sidecarAwareDirectRunnerContract.directRunnerSelected,
    sidecarAwareResidentSequence,
    sidecarAwareResidentSequenceStatus: sidecarAwareResidentSequence?.status ?? null,
    gpuAuthoritativeState: false,
    scientificValidation: false,
    sphValidation: false,
    phaseChangeValidation: false,
    fullPhysicsValidation: false
  };
}

export async function runMlsMpmMechanicsOnlyResidentStepsWithOptionalWebGpu({
  stepCount = 1,
  retainIntermediateSteps = false,
  compactSummaryMode = MLS_MPM_RESIDENT_COMPACT_SUMMARY_MODE_EVERY_STEP,
  compactSummaryScope = MLS_MPM_RESIDENT_SUMMARY_SCOPE_FULL,
  onResidentStageProgress = null,
  ...args
} = {}) {
  const count = Math.max(1, Math.round(finiteNumber(stepCount, 1)));
  const resolvedCompactSummaryMode = normalizeMlsMpmResidentCompactSummaryMode(compactSummaryMode);
  const resolvedCompactSummaryScope = normalizeMlsMpmResidentSummaryScope(compactSummaryScope);
  let sphParticleState = args.sphParticleState;
  let mlsMpmParticleState = args.mlsMpmParticleState;
  let sphParticleUpload = args.sphParticleUpload ?? null;
  let mlsMpmParticleUpload = args.mlsMpmParticleUpload ?? null;
  let sourceSlot = args.sourceSlot ?? sphParticleUpload?.slot ?? 0;
  let finalStep = null;
  const retainedSteps = [];
  const stepSummaries = [];
  const markSequenceProgress = (status, extra = {}) => {
    if (typeof onResidentStageProgress !== 'function') return;
    try {
      onResidentStageProgress({
        schema: 'peercompute.ulg.mls-mpm-mechanics-only-sequence-progress.v0',
        status,
        stepCount: count,
        compactSummaryMode: resolvedCompactSummaryMode,
        compactSummaryScope: resolvedCompactSummaryScope,
        updatedAtMs: nowMs(),
        ...extra
      });
    } catch {
      // Diagnostic progress must never affect the physics sequence.
    }
  };

  markSequenceProgress('mechanics-only-sequence-started');

  for (let index = 0; index < count; index += 1) {
    const summarizeStep = compactSummaryModeRequestsReadback(resolvedCompactSummaryMode)
      && (resolvedCompactSummaryMode !== MLS_MPM_RESIDENT_COMPACT_SUMMARY_MODE_FINAL_ONLY || index === count - 1);
    markSequenceProgress('mechanics-only-sequence-step-started', {
      stepIndex: index,
      summarizeStep
    });
    const stepArgs = {
      ...args,
      sphParticleState,
      mlsMpmParticleState,
      sphParticleUpload,
      mlsMpmParticleUpload,
      sourceSlot,
      compactSummaryScope: resolvedCompactSummaryScope,
      sequenceIndex: index,
      sequenceStepCount: count,
      internalPressureScale: 0,
      pressureInterfaceForceRowsBuffer: null,
      pressureInterfaceForceSolver: null,
      onResidentStageProgress(progress = {}) {
        markSequenceProgress(progress.status || 'mechanics-only-stage-progress', {
          ...progress,
          stepIndex: progress.stepIndex ?? progress.sequenceIndex ?? index,
          summarizeStep
        });
      }
    };
    if (!summarizeStep) stepArgs.summaryRunner = null;
    const step = await runMlsMpmMechanicsOnlyResidentStepWithOptionalWebGpu(stepArgs);
    step.sequenceIndex = index;
    stepSummaries.push(summarizeResidentStepForSequence(step, index));
    markSequenceProgress('mechanics-only-sequence-step-complete', {
      stepIndex: index,
      summarizeStep,
      backend: step.backend,
      stageTiming: step.stageTiming || null
    });
    if (finalStep && !retainIntermediateSteps) {
      destroyMlsMpmResidentStepBuffers(finalStep, {
        destroyInputResidentProductMass: true,
        preserveBuffers: retainedContinuationBuffersFromUploads(step.nextParticleUploads)
      });
    } else if (finalStep) {
      retainedSteps.push(finalStep);
    }
    finalStep = step;
    sphParticleState = cloneSphParticleStateForNext(sphParticleState, step);
    mlsMpmParticleState = cloneMlsMpmParticleStateForNext(mlsMpmParticleState, step);
    sphParticleUpload = step.nextParticleUploads?.sphParticleUpload ?? null;
    mlsMpmParticleUpload = step.nextParticleUploads?.mlsMpmParticleUpload ?? null;
    sourceSlot = step.particlePingPong?.nextSlot ?? (sourceSlot === 0 ? 1 : 0);
  }

  markSequenceProgress('mechanics-only-sequence-complete', {
    completedStepCount: stepSummaries.length,
    backend: finalStep?.backend || 'cpu-reference'
  });

  const execution = {
    schema: ULG_MLS_MPM_GPU_RESIDENT_STEPS_EXECUTION_SCHEMA,
    backend: finalStep?.backend || 'cpu-reference',
    status: 'mechanics-only-resident-steps-executed',
    stepCount: count,
    completedStepCount: stepSummaries.length,
    compactSummaryMode: resolvedCompactSummaryMode,
    compactSummaryScope: resolvedCompactSummaryScope,
    retainIntermediateSteps,
    retainedIntermediateStepCount: retainedSteps.length,
    retainedSteps,
    finalStep,
    stepSummaries,
    nextSphParticleState: sphParticleState,
    nextMlsMpmParticleState: mlsMpmParticleState,
    nextParticleUploads: finalStep?.nextParticleUploads ?? null,
    nextResidentProductMass: null,
    nextParticleBufferMode: finalStep?.nextParticleBufferMode ?? 'not-available',
    readbackMode: finalStep?.readbackMode ?? FULL_READBACK_MODE,
    fullParticleReadbackPerformed:
      finalStep?.fullParticleReadbackPerformed === true,
    normalHotLoopReadbackFree: Boolean(finalStep?.normalHotLoopReadbackFree),
    renderStateReadbackAvailable: finalStep?.renderStateReadbackAvailable ?? true,
    residentAuthorityLedgerStatus: finalStep?.residentAuthorityLedgerStatus ?? null,
    residentAuthorityFamilyOwners: compactResidentAuthorityFamilyOwners(
      finalStep?.residentAuthorityFamilyOwners || finalStep?.residentAuthoritySummary?.familyOwners
    ),
    residentAuthorityWarnings: [...(finalStep?.residentAuthorityWarnings || [])],
    residentAuthorityBlockers: [...(finalStep?.residentAuthorityBlockers || [])],
    residentBufferLeaseLedgerStatus: finalStep?.residentBufferLeaseLedgerStatus ?? null,
    residentBufferLeaseResourceCount: finalStep?.residentBufferLeaseResourceCount ?? 0,
    residentBufferLeaseActiveLeaseCount: finalStep?.residentBufferLeaseActiveLeaseCount ?? 0,
    residentBufferLeaseWarnings: [...(finalStep?.residentBufferLeaseWarnings || [])],
    residentBufferLeaseBlockers: [...(finalStep?.residentBufferLeaseBlockers || [])],
    gpuAuthoritativeState: false,
    scientificValidation: false,
    sphValidation: false,
    phaseChangeValidation: false,
    fullPhysicsValidation: false
  };
  return {
    ...execution,
    mechanicsOnlyExecutionPath: {
      schema: 'peercompute.ulg.mls-mpm-mechanics-only-execution-path.v0',
      status: 'mechanics-only-entrypoint-enforced',
      source: 'runMlsMpmMechanicsOnlyResidentStepsWithOptionalWebGpu',
      stepSource: 'runMlsMpmMechanicsOnlyResidentStepWithOptionalWebGpu',
      disabledLawStages: ['thermal', 'reaction', 'mechanicsRefresh', 'pressure-interface'],
      authoritativeWriteFamilies: ['particle-kinematics', 'mechanics'],
      suppressesPressureInterfaceForces: true,
      internalPressureScale: 0,
      scientificValidation: false,
      fullPhysicsValidation: false
    }
  };
}

export function destroyMlsMpmResidentStepsBuffers(execution, {
  preserveBuffers = []
} = {}) {
  for (const step of execution?.retainedSteps ?? []) {
    destroyMlsMpmResidentStepBuffers(step, { destroyInputResidentProductMass: true, preserveBuffers });
  }
  destroyMlsMpmResidentStepBuffers(execution?.finalStep, { destroyInputResidentProductMass: true, preserveBuffers });
}
